__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"lorePack",{enumerable:!0,get:function(){return f}});var t=r(d[0]),n=r(d[1]),o=r(d[2]),l=r(d[3]),s=r(d[4]),c=r(d[5]),p=r(d[6]),u=r(d[7]),h=r(d[8]),w=r(d[9]);const f={entries:{...t.chapters1,...n.chapters2,...o.classes,...l.races,...s.zones1,...c.zones2,...p.instances1,...u.instances2,...h.items,...w.terms},eras:{creation:{title:"Titani e Dei Antichi",when:"Prima della storia scritta"},"ancient-kalimdor":{title:"L\u2019impero dei Kaldorei",when:"Diecimila anni e pi\xf9 prima del Portale Oscuro"},"elder-kingdoms":{title:"I regni antichi",when:"Circa da 7.000 a 200 anni prima del Portale Oscuro"},draenor:{title:"Gli orchi di Draenor",when:"I decenni prima del Portale Oscuro"},"first-war":{title:"La Prima Guerra",when:"L\u2019apertura del Portale Oscuro (anno 0)"},"second-war":{title:"La Seconda Guerra",when:"Pochi anni dopo il Portale Oscuro"},interwar:{title:"Tra le guerre",when:"Gli anni dopo la Seconda Guerra"},"third-war":{title:"La Terza Guerra",when:"Circa vent\u2019anni dopo il Portale Oscuro"},"new-homes":{title:"Nuove patrie a Kalimdor",when:"Gli anni dopo la Terza Guerra"},classic:{title:"L\u2019era di World of Warcraft",when:"Anno 25 dopo il Portale Oscuro, l\u2019epoca di Forever"},beyond:{title:"Dopo Classic",when:"Espansioni successive (non fanno parte di Forever)"}},categories:{chapter:"La storia di Warcraft",class:"Classi",race:"Razze",zone:"Zone",instance:"Spedizioni e incursioni",item:"Oggetti leggendari",term:"Glossario"},notice:"Testo originale scritto per WoW Forever Path. I fatti sono stati verificati con le fonti indicate; le pagine di warcraft.wiki.gg (CC BY-SA 4.0) e gli articoli di Blizzard sono serviti da riferimento, senza copiarne il testo. World of Warcraft e Blizzard sono marchi di Blizzard Entertainment, Inc."}},1721,[1770,1771,1772,1773,1774,1775,1776,1777,1778,1779]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"chapters1",{enumerable:!0,get:function(){return o}});const o={"chapter:titans-and-old-gods":{title:"I Titani e gli Dei Antichi",summary:"Prima di ogni regno mortale, i Titani del Pantheon combatterono gli Dei Antichi per l\u2019anima di un mondo giovane, e Azeroth ne porta ancora le cicatrici.",when:"Prima della storia scritta",body:["Molto prima che i mortali tenessero memoria di alcunch\xe9, i Titani percorrevano l\u2019immensa oscurit\xe0 del cosmo: anime-mondo cresciute fino a diventare giganti viventi. I pi\xf9 nobili si riunirono nel Pantheon e scrutarono le stelle in cerca di anime-mondo dormienti come le loro. Nelle profondit\xe0 di Azeroth ne percepirono una dalle promesse straordinarie, ma poteri pi\xf9 oscuri l\u2019avevano trovata per primi.","I Signori del Vuoto avevano scagliato i loro servitori, gli Dei Antichi, sul giovane mondo. Y'Shaarj, C'Thun, Yogg-Saron e N'Zoth affondarono i loro corpi nella crosta e innalzarono l\u2019Impero Nero, con i Signori Elementali del fuoco, della terra, dell\u2019aria e dell\u2019acqua come generali. Quando il Pantheon arriv\xf2, i suoi eserciti forgiati dai Titani distrussero le cittadelle dell\u2019impero. Il Padre Supremo Aman'Thul strapp\xf2 Y'Shaarj dal suolo, ma il colpo apr\xec una ferita da cui sgorgava la linfa arcana del mondo. I Titani compresero che uccidere gli altri avrebbe potuto uccidere Azeroth stessa.","Cos\xec i guardiani scelsero le prigioni. C'Thun, Yogg-Saron e N'Zoth furono incatenati nelle profondit\xe0 della terra e i Signori Elementali furono esiliati nel Piano Elementale, i cui reami comprendono Skywall e le Terre del Fuoco. I guardiani placarono la ferita sanguinante trasformandola in un lago splendente, il Pozzo dell\u2019Eternit\xe0, plasmarono monti e mari e lasciarono camere dei Titani come Uldaman. Dopo la caduta di un mostruoso protodrago chiamato Galakrond, il Pantheon elev\xf2 cinque grandi draghi al rango di Aspetti perch\xe9 proteggessero il mondo, poi ripart\xec verso le stelle."]},"chapter:sargeras-and-the-burning-legion":{title:"Sargeras e la Legione Infuocata",summary:"Il pi\xf9 grande campione del Pantheon perse la fede nel creato e scaten\xf2 una crociata demoniaca per bruciarlo, e Azeroth divenne il premio che desiderava di pi\xf9.",when:"Molto prima degli Elfi della Notte",body:["Sargeras era il campione del Pantheon, il Titano che dava la caccia ai demoni in tutto il cosmo e li rinchiudeva in un mondo prigione chiamato Mardum. Nel corso di ere di guerra scopr\xec ci\xf2 che i Signori del Vuoto volevano davvero: corrompere un\u2019anima-mondo e generare un Titano oscuro tutto loro. Convinto che il creato avesse difetti ormai irrimediabili, decise che sarebbe stato pi\xf9 misericordioso bruciare ogni cosa.","Distrusse la prigione di Mardum e liber\xf2 i suoi demoni come prime schiere della Legione Infuocata. Sul mondo di Argus offr\xec conoscenza e potere agli eredar; i loro capi, Kil'jaeden e Archimonde, accettarono, mentre il profeta Velen fugg\xec con chi si era rifiutato, il popolo che in seguito sarebbe stato chiamato draenei. Il Pantheon tent\xf2 di fermare il suo antico campione e cadde per mano sua.","Da allora la Legione pass\xf2 di mondo in mondo, guidata da Sargeras e servita dagli eredar, dai Signori del Terrore chiamati nathrezim e da innumerevoli demoni minori. Azeroth contava pi\xf9 della maggior parte dei mondi: un\u2019anima-mondo ancora dormiente, gi\xe0 segnata dagli Dei Antichi. All\u2019epoca di World of Warcraft la Legione l\u2019aveva invasa due volte, e i suoi sussurri avevano plasmato la storia di elfi, orchi e umani."]},"chapter:rise-of-the-kaldorei":{title:"L\u2019ascesa dei Kaldorei",summary:"I troll dominavano l\u2019antico Kalimdor finch\xe9 una trib\xf9 attratta dal Pozzo dell\u2019Eternit\xe0 non divenne gli Elfi della Notte, la cui regina Azshara costru\xec un impero di magia straordinaria.",when:"Circa 15.000-10.000 anni prima del Portale Oscuro",body:["Nelle ere successive alla partenza dei Titani, Kalimdor era un unico grande continente. I troll guidati dagli Zandalari combatterono una lunga guerra contro gli aqir, creature simili a insetti, resti dei servitori degli Dei Antichi, e li ricacciarono agli estremi nord e sud della terra, dove i loro discendenti sarebbero diventati i nerubiani e i qiraji. Dopo la vittoria i troll si divisero in imperi rivali, come quelli dei Gurubashi e degli Amani.","Una trib\xf9 di troll scelse una strada pi\xf9 tranquilla. Si stabil\xec sulle rive del Pozzo dell\u2019Eternit\xe0 e, generazione dopo generazione, il potere del Pozzo la trasform\xf2: il suo popolo divenne pi\xf9 alto e longevo, vener\xf2 la dea lunare Elune e si diede il nome di Kaldorei, \u201cfigli delle stelle\u201d. Guidati dal semidio Cenarius e da altri antichi spiriti della natura, presto superarono in splendore i loro cugini troll.","La loro sovrana pi\xf9 grande fu la regina Azshara, adorata dal suo popolo e servita dagli Highborne, un\u2019aristocrazia di stregoni che attingeva sempre pi\xf9 potere dal Pozzo. Il suo palazzo di Zin-Azshari sorgeva sulla riva, e il suo impero si estendeva su tutto Kalimdor. La fame di magia degli Highborne, per\xf2, mand\xf2 onde ben oltre il mondo, e qualcosa di immenso nella Distorsione Fatua le avvert\xec."]},"chapter:war-of-the-ancients":{title:"La Guerra degli Antichi",summary:"Azshara apr\xec la via alla Legione Infuocata, e il mondo quasi fin\xec prima che il Pozzo dell\u2019Eternit\xe0 si lacerasse.",when:"Circa 10.000 anni prima del Portale Oscuro",body:["Sargeras sussurr\xf2 ad Azshara e ai suoi Highborne, promettendo un mondo rifatto a loro immagine. Gli credettero e, attraverso il Pozzo dell\u2019Eternit\xe0, aprirono un portale per la Legione Infuocata. I demoni guidati da Archimonde e Mannoroth dilagarono su Kalimdor e cominciarono a massacrare proprio i Kaldorei su cui regnava la regina.","La resistenza si raccolse attorno a capi improbabili: Malfurion Grantempesta, il primo Elfo della Notte ad apprendere il druidismo da Cenarius; suo fratello gemello Illidan, uno stregone di grande talento; e Tyrande Soffiabrezza, sacerdotessa di Elune. I semidei della natura e la maggior parte degli stormi di draghi combatterono al loro fianco. L\u2019Aspetto nero Neltharion offr\xec un\u2019arma, l\u2019Anima dei Draghi, ma la rivolse contro i suoi alleati; quel tradimento gli sarebbe valso il nome di Alamorte.","Quando Sargeras stesso tent\xf2 di varcare il portale, Malfurion e i suoi alleati spezzarono l\u2019incantesimo degli Highborne. Il Pozzo, instabile, implose, e segu\xec la Grande Frattura: il mare inghiott\xec Zin-Azshari, Kalimdor and\xf2 in pezzi e una tempesta chiamata Maelstrom cominci\xf2 a vorticare dove prima c\u2019era il Pozzo. Azshara e la sua corte scomparvero sotto le onde, per tornare un giorno come naga. Da quell\u2019unico continente nacquero le terre oggi note come Kalimdor, i Regni Orientali e Nordania."]},"chapter:the-long-watch-of-hyjal":{title:"La lunga veglia di Hyjal",summary:"I sopravvissuti fecero crescere un Albero del Mondo sopra un secondo Pozzo, imprigionarono Illidan sottoterra e montarono la guardia per diecimila anni.",when:"Da circa 10.000 anni prima del Portale Oscuro",body:["Gli Elfi della Notte sfuggiti alla Frattura si radunarono sul Monte Hyjal. L\xec scoprirono che Illidan aveva portato con s\xe9 fiale dell\u2019acqua del vecchio Pozzo e ne aveva versata una parte in un lago di montagna, creando un nuovo Pozzo dell\u2019Eternit\xe0. Temendo che un giorno potesse richiamare la Legione, Malfurion e Cenarius imprigionarono Illidan nelle Barrow Deeps, una prigione sotterranea dove la carceriera Maiev Cantombroso lo avrebbe sorvegliato per diecimila anni.","Tre Aspetti, Alexstrasza, Ysera e Nozdormu, risposero facendo crescere Nordrassil, l\u2019Albero del Mondo, sopra il nuovo Pozzo. Le sue radici sigillarono le acque e la sua benedizione don\xf2 agli Elfi della Notte l\u2019immortalit\xe0 e ai druidi un legame con il Sogno di Smeraldo, dove molti di loro dormivano per secoli. Tyrande guidava la Sorellanza di Elune e le Sentinelle, che proteggevano le foreste mentre i druidi sognavano. La magia arcana fu bandita tra i Kaldorei.","Non tutti gli Highborne obbedirono. Alcuni furono esiliati oltre il mare e fondarono Quel'Thalas; altri, gli Shen'dralar, si nascosero nella citt\xe0 di Eldre'Thalas, nell\u2019odierno Feralas. Le sue rovine oggi sono note come Maglio Infausto."]},"chapter:exiles-of-quelthalas":{title:"Gli esuli di Quel'Thalas",summary:"Highborne banditi attraversarono il mare, accesero il Pozzo Solare e costruirono un regno elfico nelle foreste settentrionali di Lordaeron.",when:"Circa 6.800 anni prima del Portale Oscuro",body:["Molto tempo dopo la Frattura, un gruppo di Highborne non riusciva ancora a rinunciare all\u2019arcano. I loro incantesimi sconsiderati scatenarono tempeste su Valtetra, e alla fine gli Elfi della Notte li bandirono. Guidati da Dath'Remar Solealto, gli esuli navigarono verso est attraverso il Grande Mare e vagarono per anni nel nuovo continente in cerca di una terra dove la magia scorresse potente.","Circa 6.800 anni prima del Portale Oscuro la trovarono nel nord di Lordaeron. Dath'Remar vers\xf2 una fiala rubata di acqua del Pozzo dell\u2019Eternit\xe0 in un lago posto su un nodo di linee di energia arcana, e il Pozzo Solare divamp\xf2. Intorno a esso sorsero Quel'Thalas e la sua capitale, Lunargenta. Vivendo sotto il sole anzich\xe9 sotto la luna, gli esuli cambiarono nel corso dei secoli e divennero gli Alti Elfi, i quel'dorei.","La terra non era deserta. Custodiva antiche rovine sacre ai troll Amani, che attaccarono i nuovi arrivati in numero schiacciante. Gli elfi li respinsero con la magia ed eressero Ban'dinoriel, una barriera di pietre runiche che tenne lontani gli Amani. Per circa quattromila anni Quel'Thalas prosper\xf2 al suo riparo, mentre i troll attendevano la vendetta."]},"chapter:arathor-and-the-troll-wars":{title:"Arathor e le Guerre dei Troll",summary:"Le trib\xf9 sparse dell\u2019umanit\xe0 si unirono sotto re Thoradin, e un\u2019alleanza con gli elfi spezz\xf2 l\u2019Impero Amani ai piedi delle Montagne d\u2019Alterac.",when:"Circa 2.800 anni prima del Portale Oscuro",body:["Per millenni le trib\xf9 umane dei Regni Orientali si combatterono a vicenda, mentre i predoni Amani colpivano da nord. Circa 2.800 anni prima del Portale Oscuro, Thoradin della trib\xf9 degli Arathi cap\xec che un\u2019umanit\xe0 divisa sarebbe stata distrutta. Con matrimoni, promesse e conquiste un\xec le trib\xf9 nel regno di Arathor e ne costru\xec la capitale, la citt\xe0-fortezza di Strom, negli attuali Altipiani di Arathi.","Gli Amani, rinvigoriti con l\u2019aiuto degli Zandalari, assalirono Quel'Thalas in numero enorme. Gli elfi si rivolsero ad Arathor. In cambio di soldati umani accettarono di insegnare la magia a cento umani scelti, i primi maghi umani. Insieme, elfi e umani schiacciarono l\u2019esercito Amani ai piedi delle Montagne d\u2019Alterac, e il fuoco dei maghi disperse i troll cos\xec a fondo che il loro impero non si riprese mai pi\xf9.","Per gratitudine, gli elfi di Quel'Thalas giurarono fedelt\xe0 alla stirpe dei re di Arathor. Strom prosper\xf2 e il suo popolo si diffuse in tutto il nord. Gli Amani si sarebbero rialzati molte altre volte, e negli Entroterre e negli Altipiani di Arathi le trib\xf9 dei troll delle foreste infestano ancora le rovine di quell\u2019antica guerra."]},"chapter:guardians-and-the-seven-kingdoms":{title:"I Guardiani e i Sette Regni",summary:"La magia umana attir\xf2 i demoni, cos\xec i maghi fondarono Dalaran e scelsero dei Guardiani che combattessero in segreto, mentre Arathor si divideva in sette regni.",when:"I millenni dopo le Guerre dei Troll",body:["La magia si diffuse in Arathor pi\xf9 in fretta della saggezza. Gli incantesimi dei maghi assottigliarono le mura del mondo e attirarono l\u2019attenzione dei demoni, cos\xec gli Alti Elfi e i maghi umani formarono il Consiglio di Tirisfal. In segreto, il consiglio sceglieva un unico Guardiano che custodisse il loro potere congiunto e desse la caccia agli agenti della Legione Infuocata.","I maghi costruirono anche una citt\xe0 tutta loro, Dalaran, dove avrebbe governato il Kirin Tor. Nel frattempo gli eredi di Arathor si allontanarono da Strom e, nel corso dei secoli, l\u2019impero si frantum\xf2 in sette regni umani: Lordaeron, Stromgarde, Gilneas, Alterac, Kul Tiras, Dalaran e, a sud, Roccavento, a lungo chiamato regno di Azeroth.","La Guardiana pi\xf9 famosa fu Aegwynn, che a Nordania abbatt\xe9 un avatar dello stesso Sargeras e ne sigill\xf2 il corpo in una tomba sotto il mare. Non seppe mai che lo spirito del Titano oscuro si era insinuato in lei. Quando diede alla luce un figlio, Medivh, lo spirito pass\xf2 a lui, e l\u2019ultimo Guardiano crebbe con un traditore nascosto nell\u2019anima. Dalla sua torre di Karazhan, un giorno avrebbe aperto la porta agli orchi."]},"chapter:war-of-the-three-hammers":{title:"La Guerra dei Tre Martelli",summary:"I tre clan nanici di Forgiardente si contesero il trono, e un thane stregone sconfitto evoc\xf2 Ragnaros, che bruci\xf2 la terra fino a formare il Massiccio Roccianera.",when:"Circa 230 anni prima del Portale Oscuro",body:["Sotto le nevi di Dun Morogh i nani scavarono Forgiardente, un regno di pietra e di mestiere che faceva risalire le sue radici ai Terrigeni dei Titani. Tre clan lo condividevano a fatica: i Barbabronzea, i Granmartello e i Ferroscuro, amanti della stregoneria. Quando mor\xec il re supremo Modimus Anvilmar, circa 230 anni prima del Portale Oscuro, la loro rivalit\xe0 esplose in guerra civile.","I Barbabronzea vinsero e cacciarono gli altri. I Granmartello costruirono Grim Batol a est, e i Ferroscuro fondarono un regno tutto loro a sud, nelle Montagne Crestarossa. Il thane stregone Thaurissan non riusc\xec ad accettare la sconfitta. Attacc\xf2 entrambi i rivali insieme, ma i suoi eserciti furono distrutti e sua moglie Modgud cadde a Grim Batol.","Disperato, Thaurissan cerc\xf2 un potere pi\xf9 grande ed evoc\xf2 Ragnaros il Signore del Fuoco, un Signore Elementale che i Titani avevano imprigionato. L\u2019arrivo del Signore del Fuoco uccise il thane, squarci\xf2 la terra formando la Gola Rovente e le Steppe Ardenti e sollev\xf2 il Massiccio Roccianera, dove i Ferroscuro sopravvissuti divennero suoi schiavi. I Granmartello abbandonarono la maledetta Grim Batol per gli Entroterre. I loro vicini gnomi, la cui citt\xe0 di Gnomeregan sorgeva l\xec vicino, divennero fedeli amici di Forgiardente."]},"chapter:corruption-of-the-orcs":{title:"La corruzione degli orchi",summary:"Sul lontano Draenor, Kil'jaeden trasform\xf2 i clan sciamanici degli orchi in un\u2019Orda sanguinaria legata dal sangue demoniaco.",when:"I decenni prima del Portale Oscuro",body:["Sul mondo di Draenor gli orchi vivevano in fieri clan di cacciatori e sciamani, onorando gli antenati e gli spiriti degli elementi. Condividevano il loro mondo, non senza tensioni, con i draenei, gli eredar fuggiti da Argus con Velen. Kil'jaeden non aveva mai smesso di dare la caccia a quegli esuli, e negli orchi vide un\u2019arma.","Travestito da spirito della defunta moglie di Ner'zhul, il signore dei demoni sussurr\xf2 all\u2019anziano sciamano e lo mise contro i draenei. Quando Ner'zhul esit\xf2, Kil'jaeden trov\xf2 un allievo pi\xf9 volenteroso in Gul'dan, che fond\xf2 il segreto Concilio dell\u2019Ombra e insegn\xf2 agli orchi la magia vile; furono i primi stregoni. Gli elementi tacquero e la verde terra degli orchi cominci\xf2 a morire.","Durante un grande raduno i capiclan bevvero il sangue del signore degli abissi Mannoroth, e Grom Malogrido del clan Cantaguerra bevve per primo. Colma di furia demoniaca, l\u2019Orda unita si abbatt\xe9 sui draenei e quasi li stermin\xf2. Solo il clan dei Lupi Bianchi di Durotan rimase in parte in disparte. Finito il massacro, Gul'dan aveva bisogno di una nuova guerra, e il padrone di Kil'jaeden ne aveva gi\xe0 una pronta su Azeroth."]},"chapter:the-first-war":{title:"Il Portale Oscuro e la Prima Guerra",summary:"Medivh aiut\xf2 gli orchi ad aprire il Portale Oscuro, e l\u2019Orda travolse il regno di Roccavento.",when:"Anno 0: il Portale Oscuro si apre",body:["Guidati da un Medivh posseduto, gli stregoni di Gul'dan e il Guardiano aprirono uno squarcio tra Draenor e Azeroth nella Palude Nera, l\u2019acquitrino che in seguito avvizz\xec fino a diventare le Terre Devastate. Gli orchi si riversarono attraverso quello che divenne noto come il Portale Oscuro, e i loro esploratori trovarono presto i ricchi campi del regno di Azeroth, l\u2019attuale Roccavento.","Re Llane Wrynn e il suo campione Anduin Lothar resistettero per anni. L\u2019apprendista stesso di Medivh, Khadgar, scopr\xec il tradimento del suo maestro e, con Lothar e la mezzorca Garona, affront\xf2 il Guardiano a Karazhan e lo uccise. La vittoria arriv\xf2 troppo tardi. Le bande da guerra dell\u2019Orda misero il regno a ferro e fuoco, e all\u2019interno dell\u2019Orda l\u2019astuto Orgrim Martelfato abbatt\xe9 Manonera e divenne Capoguerra.","Garona, vincolata dagli incantesimi di Gul'dan, assassin\xf2 re Llane, e la citt\xe0 di Roccavento cadde tra le fiamme. Lothar radun\xf2 i sopravvissuti, tra cui il giovane figlio di Llane, Varian, e li guid\xf2 oltre il mare fino a Lordaeron. Lontano a est, nelle Riverglades, una regione che esiste solo in Forever, l\u2019Orda rase al suolo il villaggio di Sunnyglade e port\xf2 via i sopravvissuti come schiavi."]},"chapter:the-second-war":{title:"La Seconda Guerra",summary:"I regni umani, gli elfi, i nani e gli gnomi si unirono nell\u2019Alleanza di Lordaeron e spezzarono l\u2019Orda di Martelfato al Bastione Roccianera.",when:"Circa cinque o sei anni dopo il Portale Oscuro",body:["L\u2019avvertimento di Lothar spinse re Terenas Menethil di Lordaeron a riunire i regni umani. Formarono l\u2019Alleanza di Lordaeron, con Lothar come comandante supremo; si unirono a loro i nani di Forgiardente, gli gnomi e, fedeli al loro antico giuramento verso la stirpe di Arathor, gli Alti Elfi di Quel'Thalas. Per dare speranza ai soldati, l\u2019arcivescovo Alonsus Faol fond\xf2 i Cavalieri della Mano d\u2019Argento, i primi paladini, con Uther il Portatore di Luce alla loro guida.","Anche l\u2019Orda di Martelfato era cresciuta. Ogre, troll Amani guidati da Zul'jin e genieri goblin combattevano al fianco degli orchi; il clan Fauci di Drago us\xf2 l\u2019Anima dei Draghi di Alamorte per rendere schiavi i draghi rossi a Grim Batol; Gul'dan cre\xf2 i primi cavalieri della morte. L\u2019Orda invase Khaz Modan, diede alle fiamme parte di Quel'Thalas e assedi\xf2 la capitale di Lordaeron.","Nel momento decisivo, Gul'dan trad\xec Martelfato e salp\xf2 per far emergere la Tomba di Sargeras, portando con s\xe9 due clan, gli Stormreaver e il Martello del Crepuscolo. Indebolita, l\u2019Orda ripieg\xf2 sul Massiccio Roccianera. Nella battaglia al Bastione Roccianera, Martelfato uccise Lothar, ma il luogotenente di Lothar, Turalyon, spezz\xf2 l\u2019Orda e Khadgar distrusse il Portale Oscuro. Gli orchi sopravvissuti furono rinchiusi in campi di internamento. Nelle Riverglades di Forever, ogre del Martello del Crepuscolo e orchi Stormreaver in fuga dalla Tomba trovarono una nuova casa."]}}},1770,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"chapters2",{enumerable:!0,get:function(){return o}});const o={"chapter:beyond-the-dark-portal":{title:"Oltre il Portale Oscuro",summary:"Ner'zhul riapr\xec il portale e fece a pezzi Draenor, e Kil'jaeden trasform\xf2 il vecchio sciamano nel Re dei Lich.",when:"Poco dopo la Seconda Guerra",body:["Con Gul'dan morto e l\u2019Orda prigioniera, il vecchio Ner'zhul radun\xf2 gli orchi rimasti su Draenor. Riapr\xec il Portale Oscuro e mand\xf2 predoni su Azeroth a rubare potenti manufatti, sperando di aprire portali verso nuovi mondi in cui il suo popolo potesse fuggire.","L\u2019Alleanza rispose con una spedizione attraverso il portale guidata da Turalyon e Khadgar, a cui si unirono la forestale Alleria Ventolesto, il nano Kurdran Granmartello e il guerriero Danath Trollbane. Combatterono la nuova Orda in tutto Draenor, ma i portali di Ner'zhul stavano gi\xe0 squarciando il mondo. Per salvare Azeroth, la spedizione distrusse il Portale Oscuro dall\u2019altro lato, intrappolandosi tra i resti in frantumi che sarebbero diventati le Terre Esterne.","Ner'zhul fugg\xec attraverso uno dei suoi squarci, dritto nelle mani di Kil'jaeden. Il demone gli strapp\xf2 il corpo ma ne conserv\xf2 lo spirito, lo leg\xf2 a un\u2019armatura incantata e lo sigill\xf2 in un blocco di ghiaccio insieme alla lama runica Gelidanima. Scagliato nelle lande gelate di Nordania, il Trono di Ghiaccio divenne la sede di un nuovo potere: il Re dei Lich, il cui compito era diffondere una piaga di non-morte e indebolire Azeroth in vista del ritorno della Legione."]},"chapter:thrall-and-the-new-horde":{title:"Thrall e la nuova Orda",summary:"Un orco cresciuto come schiavo fugg\xec da Durnholde, riscopr\xec lo sciamanesimo e liber\xf2 il suo popolo dai campi di internamento.",when:"Gli anni prima della Terza Guerra",body:["Nei campi di internamento gli orchi sprofondarono in uno strano torpore man mano che la furia demoniaca li abbandonava. Lord Aedelas Blackmoore della fortezza di Durnholde, sulle Colline di Hillsbrad, anni prima aveva trovato un neonato orco orfano e lo aveva cresciuto come gladiatore e futura arma. Chiam\xf2 il ragazzo Thrall, una parola che significa schiavo. Solo Taretha Foxton, una giovane serva, lo tratt\xf2 con gentilezza, e con il suo aiuto Thrall riusc\xec infine a fuggire.","Libero per la prima volta, Thrall and\xf2 in cerca delle leggende del proprio popolo. Grom Malogrido gli mostr\xf2 ci\xf2 che un orco poteva essere, l\u2019anziano Orgrim Martelfato fece di lui il suo secondo, e tra il clan dei Lupi Bianchi, sulle Montagne d\u2019Alterac, lo sciamano Drek'Thar gli insegn\xf2 a parlare con gli elementi. L\xec scopr\xec di essere figlio di Durotan, il capo dei Lupi Bianchi.","Thrall, Grom e Martelfato liberarono un campo dopo l\u2019altro. Martelfato cadde in battaglia e lasci\xf2 a Thrall la sua armatura nera e il suo martello, e Thrall divenne Capoguerra di una nuova Orda fondata sull\u2019onore e sullo sciamanesimo anzich\xe9 sul sangue demoniaco. A Durnholde sconfisse Blackmoore, ma Taretha non sopravvisse. Ora Thrall voleva soltanto una patria dove il suo popolo potesse vivere in pace."]},"chapter:the-lich-king-and-the-plague":{title:"Il Re dei Lich e la piaga",summary:"Da Nordania il Re dei Lich allung\xf2 la mano verso sud, e l\u2019arcimago Kel'Thuzad diffuse una piaga di non-morte attraverso il grano di Lordaeron.",when:"Alla vigilia della Terza Guerra",body:["Pur intrappolato nel Trono di Ghiaccio, il Re dei Lich estendeva la sua mente su tutta Nordania. Conquist\xf2 il regno dei ragni di Azjol-Nerub, ne fece risorgere il popolo come servitori e costru\xec una fortezza attorno al suo trono, a Corona di Ghiaccio. Poi volse lo sguardo a sud, verso i regni umani stanchi della guerra.","A Dalaran, lo stimato arcimago Kel'Thuzad era diventato ossessionato dalla negromanzia. Quando il Kirin Tor respinse i suoi studi, rispose al richiamo del Re dei Lich, si rec\xf2 a Nordania e torn\xf2 come suo profeta. Fond\xf2 il Culto dei Dannati, che prometteva ai poveri di Lordaeron uguaglianza e vita eterna, e si serv\xec dei suoi membri per diffondere una piaga nascosta nei carichi di grano.","La piaga uccideva le sue vittime e poi le rialzava come non-morti senza volont\xe0: il Flagello. I villaggi nel nord di Lordaeron caddero uno dopo l\u2019altro, mentre i regni litigavano sulle tasse e sul costo dei campi di internamento. Quando il Kirin Tor e la Mano d\u2019Argento capirono il pericolo, la piaga si era gi\xe0 diffusa nelle province settentrionali di Lordaeron. Signori del Terrore della Legione Infuocata vegliavano sull\u2019opera del Re dei Lich, perch\xe9 doveva aprire la strada al ritorno dei loro padroni."]},"chapter:fall-of-lordaeron":{title:"La caduta di Lordaeron",summary:"Il principe Arthas insegu\xec la piaga fino alla sua origine, impugn\xf2 Gelidanima e torn\xf2 per distruggere il suo stesso regno, Quel'Thalas e Dalaran.",when:"La Terza Guerra, circa 20 anni dopo il Portale Oscuro",body:["Il principe Arthas Menethil, giovane paladino della Mano d\u2019Argento, part\xec con la maga Jaina Marefiero per fermare la piaga. A Stratholme scopr\xec che il grano della citt\xe0 era gi\xe0 contaminato e ordin\xf2 di uccidere gli abitanti prima che risorgessero come non-morti. Uther e Jaina si rifiutarono di seguirlo. Arthas insegu\xec il Signore del Terrore Mal'Ganis fino a Nordania, bruci\xf2 le proprie navi perch\xe9 i suoi uomini non potessero andarsene e si impadron\xec della lama runica Gelidanima. La spada gli prese l\u2019anima.","Arthas torn\xf2 a casa come cavaliere della morte del Re dei Lich e uccise suo padre, re Terenas, nella sua stessa sala del trono. Il Flagello travolse Lordaeron. Uther cadde difendendo l\u2019urna con le ceneri di Terenas, e Arthas guid\xf2 il suo esercito a Quel'Thalas, infranse le difese degli elfi e us\xf2 il Pozzo Solare per far risorgere Kel'Thuzad come lich. Sylvanas Ventolesto, Generale dei Forestali di Lunargenta, mor\xec combattendolo e fu rialzata come banshee.","Kel'Thuzad evoc\xf2 poi il signore dei demoni Archimonde a Dalaran, e la Legione Infuocata torn\xf2 su Azeroth. Dalaran fu distrutta e Lordaeron, il pi\xf9 grande dei regni umani, non esisteva pi\xf9. Al nord rimasero solo sopravvissuti sparsi, profughi e fanatici, mentre i non-morti di Arthas dominavano la terra."]},"chapter:battle-for-mount-hyjal":{title:"La battaglia del Monte Hyjal",summary:"Avvertiti da un profeta, orchi e umani salparono per Kalimdor, dove si unirono agli Elfi della Notte per fermare Archimonde davanti all\u2019Albero del Mondo.",when:"La fine della Terza Guerra",body:["Un misterioso profeta, Medivh tornato dalla morte, esort\xf2 Thrall e Jaina a navigare verso ovest, fino a Kalimdor. L\u2019Orda di Thrall sbarc\xf2 sulle sue coste, strinse amicizia con i tauren di Cairne Zoccolo Sanguinario e si apr\xec la strada attraverso le Savane, mentre Jaina guidava i profughi di Lordaeron sullo stesso continente. Nelle foreste di Valtetra, Grom Malogrido e il suo clan Cantaguerra bevvero di nuovo il sangue demoniaco e uccisero il semidio Cenarius.","Thrall e Jaina collaborarono per la prima volta per salvare Grom. In un ultimo duello Grom uccise Mannoroth, liberando gli orchi dalla maledizione del sangue al prezzo della propria vita. Nel frattempo Tyrande Soffiabrezza risvegli\xf2 i druidi e liber\xf2 Illidan dalle Barrow Deeps, sperando che il suo potere fosse d\u2019aiuto. Invece lui consum\xf2 il Teschio di Gul'dan, divenne per met\xe0 demone e fu esiliato dal suo stesso fratello.","Archimonde marci\xf2 su Nordrassil per prosciugarne il potere. Elfi della Notte, umani e orchi tennero insieme i pendii del Monte Hyjal, guadagnando tempo mentre Malfurion preparava una trappola. Quando il demone raggiunse l\u2019albero, migliaia di fuochi fatui gli si gettarono addosso e il potere di Nordrassil lo dilani\xf2. L\u2019esercito della Legione fu spezzato, ma l\u2019Albero del Mondo rimase gravemente ferito e gli Elfi della Notte persero l\u2019immortalit\xe0 che aveva donato loro."]},"chapter:rise-of-the-forsaken":{title:"L\u2019ascesa dei Reietti",summary:"Mentre il Re dei Lich si indeboliva, Sylvanas Ventolesto si liber\xf2 insieme ad altri non-morti e rivendic\xf2 le rovine di Lordaeron come Reietti.",when:"Subito dopo la Terza Guerra",body:["Dopo la caduta di Archimonde, la presa del Re dei Lich cominci\xf2 a cedere. Illidan, ormai al servizio di Kil'jaeden, colp\xec il Trono di Ghiaccio, e Arthas si precipit\xf2 a nord per difendere il suo padrone. A Lordaeron i Signori del Terrore tentarono di impadronirsi del Flagello, e nel caos molti non-morti riacquistarono la propria volont\xe0.","Sylvanas Ventolesto fu la prima. Con le sue banshee e altri non-morti liberi, e con il Signore del Terrore Varimathras costretto a servirla, sconfisse i suoi rivali e rivendic\xf2 la capitale in rovina di Lordaeron. Sotto di essa si trovavano le antiche cripte reali e le fogne, che divennero Sepulcra. Il suo popolo si chiam\xf2 Reietti: non pi\xf9 umani, rifiutati dai vivi e liberi dal Re dei Lich.","Arthas raggiunse Corona di Ghiaccio, indoss\xf2 l\u2019elmo del Re dei Lich e si fuse con lui sul Trono di Ghiaccio, poi tacque dietro il ghiaccio. Circondati da nemici, i Reietti si unirono all\u2019Orda di Thrall come alleati diffidenti, mentre il Flagello, la Crociata Scarlatta e ci\xf2 che restava della nobilt\xe0 di Lordaeron si contendevano le Terre Infette. La storia di Forever riprende dopo la campagna \u201cForsaken Kingdom\u201d di Warcraft III: Reforged, i cui eventi questa guida non tratta ancora."],unknowns:["Ci\xf2 che accade nella campagna \u201cForsaken Kingdom\u201d di Warcraft III: Reforged, che Forever prosegue, non \xe8 descritto nelle fonti usate da questa guida."]},"chapter:durotar-and-theramore":{title:"Durotar e Theramore",summary:"Thrall fond\xf2 Durotar e Orgrimmar, Jaina costru\xec Theramore, e i due mantennero una pace fragile anche quando il padre di Jaina arriv\xf2 per fare la guerra.",when:"Gli anni dopo la Terza Guerra",body:["Dopo Hyjal, Thrall condusse gli orchi in una dura terra rossa sulla costa orientale di Kalimdor e la chiam\xf2 Durotar in onore di suo padre. La loro capitale, Orgrimmar, onorava Orgrim Martelfato. I tauren di Cairne Zoccolo Sanguinario si stabilirono nelle praterie di Mulgore, attorno agli altipiani di Picco del Tuono, e i troll Lanciascura di Vol'jin, che Thrall aveva salvato durante il suo viaggio verso ovest, si stabilirono sulle Isole dell\u2019Eco, al largo della costa di Durotar.","Jaina Marefiero fond\xf2 Theramore su un\u2019isola di Acquemorte per i sopravvissuti umani che aveva portato da Lordaeron. Lei e Thrall avevano combattuto fianco a fianco a Hyjal e si accordarono per mantenere la pace. Quella pace fu messa alla prova quando suo padre, il grande ammiraglio Daelin Marefiero di Kul Tiras, arriv\xf2 con la sua flotta, deciso a distruggere gli orchi.","Daelin attacc\xf2 la costa di Durotar. Rexxar, un vagabondo mezzo ogre dei Mok'Nathal divenuto il campione dell\u2019Orda, un\xec orchi, troll e tauren contro di lui, e Jaina, divisa tra il suo popolo e suo padre, permise all\u2019Orda di colpire le sue truppe a Theramore. Daelin mor\xec in battaglia. Jaina lo pianse ma mantenne la parola, e la fragile tregua tra Theramore e Orgrimmar divenne uno dei pochi ponti tra l\u2019Alleanza e l\u2019Orda."]},"chapter:stormwind-in-shadow":{title:"Roccavento nell\u2019ombra",summary:"La ricostruita Roccavento deve affrontare una gilda di muratori tradita, un re scomparso e un drago nascosto a corte, mentre gli gnomi hanno perso la loro citt\xe0.",when:"Anno 25 dopo il Portale Oscuro",body:["Dopo la Seconda Guerra, la Gilda dei Muratori guidata da Edwin VanCleef ricostru\xec la citt\xe0 di Roccavento dalle sue ceneri. Terminato il lavoro, la Camera dei Nobili si rifiut\xf2 di pagarli. I muratori si ribellarono, furono cacciati e divennero la Confraternita Defias, che ora colpisce le Marche Occidentali da miniere nascoste e trama contro la corona.","Re Varian Wrynn, il bambino che Lothar un tempo salv\xf2, scomparve mentre si recava a un incontro diplomatico a Theramore; si dice che i Defias lo abbiano rapito e lo tengano prigioniero sull\u2019isola di Alcaz. Il suo giovane figlio Anduin fu incoronato, con l\u2019Altolord Bolvar Domadraghi come reggente. A corte, una nobildonna affascinante, Lady Katrana Prestor, acquis\xec grande influenza. In realt\xe0 era Onyxia, figlia di Alamorte, che guidava in silenzio il regno verso la rovina.","L\u2019Alleanza \xe8 cambiata. Lordaeron \xe8 perduta e gli Elfi della Notte si sono uniti all\u2019Alleanza dopo Hyjal. A Dun Morogh i trogg sono sbucati dal sottosuolo e hanno invaso Gnomeregan; il disperato tentativo degli gnomi di stanarli con le radiazioni ha avvelenato la loro stessa citt\xe0, e il Gran Inventore Mekkatorque ha condotto i sopravvissuti al riparo a Forgiardente. L\xec regna re Magni Barbabronzea, la cui Lega degli Esploratori scava in tutto il mondo alla ricerca dei segreti dei Titani."]},"chapter:fire-beneath-blackrock":{title:"Fuoco sotto Roccianera",summary:"Nel Massiccio Roccianera i nani Ferroscuro servono Ragnaros mentre gli orchi di Nefarian occupano il bastione sovrastante, e Onyxia protegge la sua covata ad Acquemorte.",when:"Anno 25 dopo il Portale Oscuro",body:["Due secoli dopo l\u2019errore di Thaurissan, i suoi discendenti regnano ancora sotto il Massiccio Roccianera. L\u2019imperatore Dagran Thaurissan tiene corte nella citt\xe0 ferroscura di Forgiascura, nel cuore delle Profondit\xe0 Roccianera, mentre pi\xf9 in basso Ragnaros arde nel Nucleo Ardente e i nani faticano per lui. La principessa Moira Barbabronzea, figlia di re Magni, arriv\xf2 nella montagna come prigioniera e rimase come sposa dell\u2019imperatore, con grande furia del padre.","Le sale superiori appartengono allo Stormo Nero. Nefarian, figlio di Alamorte, regna sulla Fortezza dell\u2019Ala Nera sotto le sembianze di Lord Victor Nefarius e comanda gli orchi Roccianera che non si unirono mai a Thrall, guidati dal Capoguerra Rend Manonera al Bastione Roccianera. Fuoco e ombra combattono una guerra fredda all\u2019interno della stessa montagna, e le Steppe Ardenti e la Gola Rovente ne pagano il prezzo.","La sorella di Nefarian, Onyxia, la falsa Lady Prestor, ha il suo covo ad Acquemorte, dove protegge la sua covata. Per raggiungerla serve il Drakefire Amulet, ottenuto con una lunga serie di missioni per ciascuna fazione che passa per il Bastione Roccianera. In Forever, il Covo di Onyxia \xe8 una delle tre incursioni che aprono il 9 dicembre, accanto a due nuove incursioni sul Monte Hyjal."]},"chapter:plaguelands-and-the-scarlet-crusade":{title:"Le Terre Infette e la Crociata Scarlatta",summary:"Il Flagello di Kel'Thuzad domina il nord, i fanatici della Crociata Scarlatta combattono non-morti e vivi allo stesso modo, e pochi ordini irriducibili resistono.",when:"Anno 25 dopo il Portale Oscuro",body:["Il cuore di Lordaeron oggi sono le Terre Infette. Kel'Thuzad vi comanda il Flagello dalla necropoli fluttuante di Naxxramas, il barone Rivendare governa i non-morti nella Stratholme in rovina e, nell\u2019antica scuola della famiglia Barov, Scholomance, il Culto dei Dannati addestra nuovi negromanti.","I sopravvissuti della Mano d\u2019Argento si riorganizzarono come Crociata Scarlatta, giurando di purgare la terra dalla piaga con il fuoco. Il loro Gran Crociato, Saidan Dathrohan, \xe8 in segreto il Signore del Terrore Balnazzar, e la Crociata \xe8 diventata cos\xec fanatica da uccidere qualsiasi estraneo sospetti di contaminazione. Tra le sue roccaforti ci sono il Monastero Scarlatto nelle Radure di Tirisfal, Hearthglen, la Mano di Tyr e un bastione a Stratholme. Persino i suoi eroi portano storie pi\xf9 cupe: Renault Mograine trad\xec suo padre Alexandros, l\u2019Ashbringer, consegnandolo alla morte.","Non tutti i paladini divennero fanatici. Chi rifiut\xf2 la crudelt\xe0 della Crociata form\xf2 l\u2019Alba d\u2019Argento, che dalla Light's Hope Chapel collabora con chiunque combatta il Flagello. Il paladino esiliato Tirion Fordring vive da eremita vicino a Hearthglen, e i Reietti avanzano verso nord da Tirisfal. Il destino di Lordaeron non \xe8 ancora deciso."]},"chapter:azeroth-in-year-twenty-five":{title:"Azeroth nell\u2019anno 25",summary:"Il mondo del primo anno di World of Warcraft, in cui \xe8 ambientata la storia di Forever: una pace fragile, vecchie minacce che si risvegliano e luoghi nuovi sulla mappa.",when:"Anno 25: l\u2019epoca di Forever",body:["Venticinque anni dopo la prima apertura del Portale Oscuro, Azeroth \xe8 un mondo di sopravvissuti. L\u2019Alleanza di Roccavento, Forgiardente, gnomi ed Elfi della Notte fronteggia un\u2019Orda di orchi, troll, tauren e Reietti, e nessuna delle due parti si fida dell\u2019altra. Ai margini della mappa si risvegliano vecchi nemici: servitori del Dio Antico C'Thun a Silithus, sacerdoti del dio del sangue Hakkar nelle rovine troll del sud e la corruzione dell\u2019Incubo di Smeraldo che si insinua nei sogni dei druidi.","World of Warcraft: Forever \xe8 ambientato proprio in questo momento. Blizzard lo mantiene l\xec a tempo indeterminato, dopo la campagna \u201cForsaken Kingdom\u201d di Warcraft III: Reforged e prima di The Burning Crusade, e afferma che la sua storia non condivide la continuit\xe0 del World of Warcraft attuale. Forever aggiunge luoghi che il gioco originale non ha mai avuto: le Riverglades a est delle Maleterre, dove Farholde Keep resiste al Martello del Crepuscolo; una Dalaran in restauro la cui barriera di occultamento \xe8 caduta; e spedizioni che vanno dalle tombe reali della Hall of Thanes alla struttura dei Titani di Shaper's Terrace.","Forever apre ai giocatori anche un nuovo popolo: gli Skyborne di Zephras Isle, un\u2019isola che fluttua in Skywall, il Piano Elementale dell\u2019Aria. I suoi elementali dell\u2019aria sono scomparsi secoli fa e la magia che tiene l\u2019isola sospesa si sta affievolendo; il suo High Order serve l\u2019Alleanza e i suoi Windshaper l\u2019Orda. Il finale di queste storie \xe8 ancora da scrivere. Blizzard ha annunciato nuove incursioni, spedizioni e una serie di missioni leggendaria per il 2027, e le incursioni del Monte Hyjal aprono il 9 dicembre."]},"chapter:after-classic":{title:"Epilogo: dopo Classic",summary:"Nella linea temporale originale la storia prosegu\xec nelle Terre Esterne, a Nordania e oltre; Forever resta nell\u2019anno 25 e racconta la propria.",when:"Espansioni successive (non fanno parte di Forever)",body:["Nella linea temporale originale di World of Warcraft la storia continu\xf2 ad andare avanti. Il Portale Oscuro si riapr\xec e The Burning Crusade port\xf2 gli avventurieri nelle Terre Esterne, dove caddero Illidan e Kael'thas Solealto. In Wrath of the Lich King l\u2019Alleanza e l\u2019Orda marciarono su Nordania, e Arthas fu sconfitto in cima alla Rocca della Corona di Ghiaccio. In Cataclysm, Alamorte emerse dalle profondit\xe0 e sfigur\xf2 il volto del mondo prima che gli Aspetti e i loro alleati mortali lo abbattessero.","Le espansioni successive portarono la saga a Pandaria, su un Draenor alternativo, alla sconfitta definitiva della Legione Infuocata su Argus, alla guerra aperta tra le fazioni, nei regni dei morti, sulle Isole dei Draghi e nella lunga lotta attorno all\u2019anima-mondo stessa di Azeroth. Molti luoghi di questa guida sono cambiati lungo il cammino fino a diventare irriconoscibili.","World of Warcraft: Forever non prende nessuna di queste strade. Resta nell\u2019anno 25, in una \u201cbolla temporale\u201d fuori dalla continuit\xe0 del gioco attuale, e costruisce il suo futuro sulle fondamenta del mondo originale. La tabella di marcia di Blizzard promette per il 2027 nuove incursioni, spedizioni, missioni e un\u2019incursione iconica rinnovata, quindi i prossimi capitoli di questa storia apparterranno soltanto a Forever."]}}},1771,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"classes",{enumerable:!0,get:function(){return o}});const o={"class:mage":{title:"Mago",summary:"Eredi degli Highborne e dei primi maghi umani, i maghi piegano il potere arcano allo stato puro, e ogni epoca della storia ruota attorno a uno di loro.",body:["I maghi padroneggiano l\u2019arcano, la magia pura dell\u2019ordine che un tempo sgorgava dal Pozzo dell\u2019Eternit\xe0. Gli Highborne degli Elfi della Notte furono i primi grandi stregoni, e i loro discendenti esiliati, gli Alti Elfi di Quel'Thalas, insegnarono quest\u2019arte a cento umani durante le Guerre dei Troll. Quei primi maghi umani fondarono poi Dalaran, dove il Kirin Tor custodisce ancora i segreti degli incantesimi.","Ogni epoca della storia ruota attorno a un mago: Medivh, l\u2019ultimo Guardiano; il suo apprendista Khadgar, che distrusse il Portale Oscuro; l\u2019arcimago Antonidas, morto difendendo Dalaran; e Jaina Marefiero, che oggi governa Theramore. Nell\u2019anno 25 nuovi allievi si formano nel Quartiere dei Maghi di Roccavento e nel Quartiere della Magia di Sepulcra, e i maghi gnomi e troll stanno da tempo al fianco di umani e Reietti. Forever apre questa strada agli orchi, i cui incantatori un tempo conoscevano solo lo sciamanesimo e la magia vile, e all\u2019High Order, gli unici Skyborne che possono diventare maghi."]},"class:warrior":{title:"Guerriero",summary:"Ogni popolo di Azeroth ha i suoi guerrieri, e buona parte della storia del mondo \xe8 stata scritta con il loro acciaio.",body:["Ogni popolo di Azeroth ha i suoi guerrieri, e buona parte della sua storia \xe8 stata scritta con il loro acciaio. I soldati di Arathor difesero il Muro di Thoradin contro gli Amani; i thane nanici combatterono per Forgiardente nella Guerra dei Tre Martelli; i clan degli orchi vivevano della forza dei loro campioni molto prima che l\u2019Orda venisse forgiata. I guerrieri si affidano all\u2019addestramento, all\u2019armatura e alla furia della battaglia anzich\xe9 agli incantesimi.","I loro eroi riempiono le cronache: Anduin Lothar, il Leone di Azeroth, che guid\xf2 l\u2019Alleanza finch\xe9 non cadde al Bastione Roccianera; Grom Malogrido, il cui sacrificio sul Monte Hyjal liber\xf2 gli orchi dal sangue demoniaco; e Danath Trollbane, rimasto su Draenor con la spedizione dell\u2019Alleanza. Nell\u2019anno 25 i guerrieri servono sotto ogni stendardo, dalle guardie di Roccavento ai soldati di Orgrimmar, e ogni razza giocabile pu\xf2 impugnare le armi. Forever aggiunge alle loro file gli Skyborne di entrambi gli ordini."]},"class:paladin":{title:"Paladino",summary:"Guerrieri sacri nati nella Seconda Guerra, i paladini della Mano d\u2019Argento furono spezzati da uno dei loro e oggi combattono sotto nuovi stendardi.",body:["I paladini sono guerrieri sacerdoti della Luce Sacra. L\u2019arcivescovo Alonsus Faol fond\xf2 il loro ordine, i Cavalieri della Mano d\u2019Argento, durante la Seconda Guerra, per dare all\u2019Alleanza campioni capaci di guarire oltre che di combattere. Uther il Portatore di Luce fu il primo di loro, e Turalyon, Tirion Fordring e il principe Arthas Menethil prestarono tutti giuramento.","L\u2019ordine fu spezzato da uno dei suoi. Arthas uccise Uther e contribu\xec a distruggere Lordaeron, e i sopravvissuti della Mano d\u2019Argento si dispersero: da una parte i fanatici della Crociata Scarlatta, dall\u2019altra l\u2019Alba d\u2019Argento e l\u2019esule Tirion. Anche i nani di Forgiardente portano la Luce in battaglia. Il cambiamento pi\xf9 sorprendente di Forever \xe8 che ora anche i Reietti possono diventare paladini, sebbene le fonti usate qui non spieghino ancora come i non-morti siano giunti a brandire la Luce."],unknowns:["Le fonti usate da questa guida non spiegano come i paladini Reietti siano giunti a brandire la Luce in Forever."]},"class:hunter":{title:"Cacciatore",summary:"Forestali, fucilieri e domatori, i cacciatori vivono dell\u2019arco, del fucile e del legame con un animale fedele.",body:["I cacciatori vivono dell\u2019arco, del fucile e del legame con una bestia. I forestali di Quel'Thalas, guidati per generazioni dalla famiglia Ventolesto, sorvegliavano le foreste degli elfi; i fucilieri nanici e i cavalcatori di grifoni Granmartello combatterono nella Seconda Guerra; le Sentinelle degli Elfi della Notte e i cacciatori di teste troll battono i boschi di Kalimdor e di Rovotorto.","Alcuni dei sopravvissuti pi\xf9 tenaci della storia sono cacciatori. Alleria Ventolesto marci\xf2 oltre il Portale Oscuro e non fece mai ritorno, sua sorella Sylvanas combatt\xe9 Arthas fino all\u2019ultimo respiro e il domatore Rexxar divenne il campione dell\u2019Orda contro Daelin Marefiero. In Forever anche gli umani possono seguire questa vocazione, ed entrambi gli ordini Skyborne contano cacciatori tra il loro popolo."]},"class:rogue":{title:"Ladro",summary:"Spie, borseggiatori e assassini, i ladri agiscono dove l\u2019onore esiterebbe, e alcune delle loro gilde hanno plasmato la storia in silenzio.",body:["I ladri agiscono dove l\u2019onore esiterebbe. Borseggiatori, spie e assassini esistono in ogni citt\xe0, ma alcune delle loro organizzazioni plasmano la storia: il servizio segreto di Roccavento, lo SI:7, guidato da Mathias Shaw; gli assassini di Ravenholdt, nascosti nelle Montagne d\u2019Alterac; il Sindacato, nato dalla nobilt\xe0 caduta in disgrazia di Alterac; e la Confraternita Defias che infesta le Marche Occidentali.","La ladra pi\xf9 famosa delle prime guerre fu Garona Halforcen, la spia mezzorca la cui lama uccise re Llane. Nell\u2019anno 25 gli istruttori dei ladri insegnano nella Citt\xe0 Vecchia di Roccavento e nel Quartiere dei Ladri di Sepulcra, e ogni razza giocabile tranne i tauren pu\xf2 imparare il mestiere. Forever aggiunge alle ombre gli Skyborne di entrambi gli ordini."]},"class:priest":{title:"Sacerdote",summary:"I sacerdoti servono la Luce Sacra, la dea lunare Elune o poteri pi\xf9 antichi e oscuri: guariscono gli alleati e, quando serve, annientano i nemici.",body:["I sacerdoti servono la fede in molte forme. La Chiesa della Luce Sacra degli umani, che ha il suo centro nella Cattedrale della Luce di Roccavento ed era un tempo guidata dall\u2019arcivescovo Alonsus Faol, insegna che la Luce vive nella virt\xf9 e non in un singolo dio, e anche i nani l\u2019hanno abbracciata. Le sacerdotesse degli Elfi della Notte servono la dea lunare Elune in una sorellanza che Tyrande Soffiabrezza guida dalla Guerra degli Antichi.","Altri percorrono sentieri pi\xf9 oscuri. I sacerdoti Reietti custodiscono una fede cupa tutta loro, i sacerdoti troll onorano i loa dei loro antenati e la magia dell\u2019Ombra fa parte dell\u2019arte di molti sacerdoti. In Forever gli gnomi, a lungo noti come un popolo di ingegneri, possono diventare sacerdoti per la prima volta, e Blizzard ha dato loro incantesimi razziali da sacerdote tutti loro."]},"class:shaman":{title:"Sciamano",summary:"Gli sciamani chiedono aiuto agli spiriti della terra, del fuoco, dell\u2019acqua e dell\u2019aria; perduta per gli orchi per una generazione, la tradizione fu restaurata da Thrall.",body:["Gli sciamani parlano con gli spiriti della terra, del fuoco, dell\u2019acqua e dell\u2019aria, e chiedono anzich\xe9 comandare. Su Draenor gli sciamani orchi erano le guide del loro popolo finch\xe9 la corruzione di Ner'zhul non li sostitu\xec con gli stregoni, e per una generazione gli elementi smisero del tutto di rispondere agli orchi. Thrall restaur\xf2 la tradizione, istruito da Drek'Thar dei Lupi Bianchi, e ricostru\xec l\u2019Orda attorno a essa.","I tauren di Mulgore e i troll Lanciascura conservano usanze sciamaniche proprie, e Thrall guida ancora gli sciamani di Orgrimmar. Forever aggiunge due nuovi arrivati: i nani, che nel gioco originale non avevano sciamani, e gli Skyborne Windshaper di Zephras Isle, la cui isola fluttua in Skywall, il Piano Elementale dell\u2019Aria."],unknowns:["Le fonti usate da questa guida non spiegano come i nani siano arrivati allo sciamanesimo in Forever."]},"class:warlock":{title:"Stregone",summary:"Maestri della magia vile e dei demoni asserviti, gli stregoni arrivarono su Azeroth con l\u2019Orda e camminano su un filo sottile tra potere e rovina.",body:["Gli stregoni traggono potere dalla magia vile e piegano i demoni al loro volere. L\u2019arte arriv\xf2 su Azeroth con l\u2019Orda: Kil'jaeden la insegn\xf2 a Gul'dan, il cui Concilio dell\u2019Ombra trasform\xf2 gli sciamani orchi in stregoni e prosciug\xf2 la vita di Draenor per alimentarne gli incantesimi. I cavalieri della morte e la maledizione del sangue demoniaco furono tra i suoi frutti pi\xf9 oscuri.","Non tutti gli stregoni servono la Legione. Gli stregoni umani si riuniscono in segreto sotto la locanda Slaughtered Lamb di Roccavento, gnomi e Reietti studiano l\u2019arte, e l\u2019Orda di Thrall tollera con diffidenza i suoi stregoni orchi. Ogni stregone cammina sullo stesso filo: il potere \xe8 reale, e lo \xe8 anche il rischio di esserne divorati. In Forever anche i troll possono diventare stregoni."]},"class:druid":{title:"Druido",summary:"Custodi mutaforma della natura, istruiti per primi dal semidio Cenarius, i druidi preservano l\u2019equilibrio del mondo, dalla Radura Lunare al Sogno di Smeraldo.",body:["I druidi custodiscono l\u2019equilibrio della natura e possono assumere la forma delle bestie. Malfurion Grantempesta apprese l\u2019arte dal semidio Cenarius e divenne il primo druido; i suoi seguaci dormirono per secoli nel Sogno di Smeraldo mentre le Sentinelle vegliavano sulle foreste degli Elfi della Notte. Il Circolo Cenariano, con sede nella sacra Radura Lunare, riunisce oggi druidi di ogni razza.","Dopo la Terza Guerra, Malfurion insegn\xf2 ai tauren le arti druidiche, e Hamuul Totem Runico divenne il primo druido tauren. Nell\u2019anno 25 i druidi hanno gravi preoccupazioni: l\u2019Albero del Mondo Nordrassil \xe8 ferito, Teldrassil \xe8 cresciuto senza la benedizione degli Aspetti e un incubo si sta diffondendo nel Sogno di Smeraldo. In Forever entrambi gli ordini Skyborne contano druidi tra il loro popolo."]}}},1772,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"races",{enumerable:!0,get:function(){return o}});const o={"race:human":{title:"Umani",summary:"Eredi di Arathor e spina dorsale dell\u2019Alleanza, gli umani hanno pagato il prezzo di ogni guerra della storia di Azeroth e tuttavia continuano a ricostruire.",body:["Gli umani discendono dalle trib\xf9 che re Thoradin un\xec in Arathor quasi tremila anni prima del Portale Oscuro. Gli eredi di Arathor fondarono i sette regni umani, gli elfi istruirono i loro primi maghi e la loro fede nella Luce Sacra diede in seguito origine ai paladini. L\u2019umanit\xe0 sostenne l\u2019Alleanza durante la Prima, la Seconda e la Terza Guerra, pagandone un caro prezzo: Roccavento bruci\xf2 una volta e Lordaeron cadde sotto il Flagello.","Nell\u2019anno 25 Roccavento \xe8 il cuore del potere umano, ricostruita in pietra bianca ma turbata dai Defias, dalla scomparsa di re Varian e da una corte stregata da Lady Prestor. I nuovi umani iniziano all\u2019Abbazia di Contea del Nord, nella Foresta di Elwynn. Forever permette agli umani di diventare cacciatori, una vocazione che il gioco originale riservava ad altre razze."]},"race:gnome":{title:"Gnomi",summary:"Geniali inventori i cui antenati erano macchine forgiate dai Titani, gli gnomi hanno perso la loro citt\xe0 di Gnomeregan e vivono in esilio a Forgiardente.",body:["Gli gnomi sono piccoli di statura e immensi in ingegno. I loro antenati, i meccagnomi, erano macchine forgiate dai Titani colpite in seguito dalla maledizione della carne, che le trasform\xf2 in esseri viventi. A Dun Morogh costruirono Gnomeregan, una citt\xe0 di ingranaggi e vapore, e divennero fedeli alleati dei nani della vicina Forgiardente, al cui fianco combatterono nella Seconda Guerra.","Quella citt\xe0 \xe8 perduta. I trogg sono sbucati dalle profondit\xe0, e il consiglio di Sicco Thermaplugg di inondare Gnomeregan di radiazioni l\u2019ha invece avvelenata; molti gnomi sono morti e alcuni sopravvissuti sono diventati deformi gnomi lebbrosi. Il Gran Inventore Gelbin Mekkatorque ha condotto gli altri in esilio a Forgiardente, mentre Thermaplugg regna sulle rovine. Forever apre per la prima volta il sacerdozio agli gnomi."]},"race:night-elf":{title:"Elfi della Notte",summary:"Gli antichi Kaldorei vegliarono su Kalimdor per diecimila anni; ora mortali, hanno piantato un nuovo Albero del Mondo e si sono uniti all\u2019Alleanza.",body:["Gli Elfi della Notte, o Kaldorei, sono il pi\xf9 antico dei popoli giocabili. Discendenti di troll trasformati dal Pozzo dell\u2019Eternit\xe0, costruirono un impero di magia, sopravvissero alla Guerra degli Antichi e trascorsero diecimila anni come un popolo schivo di druidi e Sentinelle all\u2019ombra del Monte Hyjal. La magia arcana resta proibita tra loro.","La Terza Guerra cost\xf2 loro l\u2019immortalit\xe0, quando Nordrassil fu ferito per distruggere Archimonde. Con Malfurion perduto nel Sogno di Smeraldo, l\u2019arcidruido Fandral Staghelm fece crescere un nuovo Albero del Mondo, Teldrassil, al largo di Rivafosca, e la capitale Darnassus sorse tra i suoi rami. Sotto la guida di Tyrande Soffiabrezza, gli Elfi della Notte si unirono all\u2019Alleanza. I nuovi Elfi della Notte iniziano tra le radure di Teldrassil."]},"race:dwarf":{title:"Nani",summary:"Figli dei Terrigeni dei Titani, i nani di Forgiardente sono alleati testardi, esploratori instancabili e custodi di un\u2019eredit\xe0 divisa.",body:["I nani sono testardi, generosi e nati dalla pietra: i loro antenati erano i Terrigeni, guardiani forgiati dai Titani trasformati dalla maledizione della carne. Forgiardente, scavata in una montagna di Dun Morogh, \xe8 la loro capitale da tempo immemorabile. La Guerra dei Tre Martelli divise i clan: i Barbabronzea mantennero la citt\xe0, i Granmartello si stabilirono negli Entroterre e i Ferroscuro finirono al servizio di Ragnaros.","Sotto re Magni Barbabronzea i nani hanno combattuto in ogni guerra dell\u2019Alleanza, e la Lega degli Esploratori, di cui suo fratello Brann \xe8 una figura di spicco, scava tra rovine dei Titani come Uldaman in cerca delle origini dei nani. Moira, figlia di Magni, \xe8 diventata la sposa dell\u2019imperatore dei Ferroscuro, una ferita che il re vive come un fatto personale. Forever aggiunge la Hall of Thanes sotto Forgiardente, luogo di riposo dei sovrani nanici, ora violata da intrusi che si ritiene siano Ferroscuro, e i nani possono seguire la via dello sciamano."]},"race:skyborne-high-order":{title:"Skyborne: High Order",body:["Gli Skyborne sono il nuovo popolo giocabile di World of Warcraft: Forever, e l\u2019High Order \xe8 il ramo che sta al fianco dell\u2019Alleanza. La loro patria \xe8 Zephras Isle, un\u2019isola che fluttua in Skywall, il Piano Elementale dell\u2019Aria; la governa l\u2019Alta Anziana Talaanis Shadowsong e il suo insediamento principale \xe8 la citt\xe0 di Valanaar. Gli elementali dell\u2019aria che un tempo vivevano sull\u2019isola con gli Skyborne sono scomparsi secoli fa, la magia che la sostiene si sta affievolendo e i contatti con le isole sorelle di Anvilas e Siroccas si sono interrotti, mentre i profughi fuggono verso Zephras.","Gli avventurieri dell\u2019High Order lasciano l\u2019isola in aeronave da Valanaar a Dalaran, sulle Montagne d\u2019Alterac. Possono essere guerrieri, cacciatori, ladri, druidi o maghi, e sono gli unici Skyborne che studiano l\u2019arcano. I loro doni riflettono la loro patria: scendono planando sul vento, agiscono con celerit\xe0 accresciuta, colpiscono pi\xf9 duramente gli elementali e leggono le linee di energia arcana vicine per recuperare salute e mana. Per giocarli serve lo Skyborne Heroic o Epic Pack, facoltativo."]},"race:skyborne-windshaper":{title:"Skyborne: Windshaper",body:["I Windshaper sono gli Skyborne che stanno al fianco dell\u2019Orda. Come l\u2019High Order, provengono da Zephras Isle in Skywall, il Piano Elementale dell\u2019Aria, un\u2019isola i cui elementali dell\u2019aria sono scomparsi secoli fa e la cui magia di sostegno si sta lentamente esaurendo. Mentre isole come Anvilas e Siroccas tacciono, i profughi si ammassano su Zephras, e persino Zephras ha cominciato a sgretolarsi.","I Windshaper lasciano Valanaar in aeronave per lo Skywatcher Plateau, a Mulgore. Possono essere guerrieri, cacciatori, ladri, druidi o sciamani, e sono gli unici Skyborne che seguono la via dello sciamano. Planano sul vento, combattono con celerit\xe0 accresciuta e colpiscono pi\xf9 duramente gli elementali, e il loro dono speciale, Skysight, accelera i loro viaggi e dura molto pi\xf9 a lungo vicino a una convergenza elementale. Come l\u2019High Order, richiedono lo Skyborne Heroic o Epic Pack, facoltativo."]},"race:orc":{title:"Orchi",summary:"Un tempo schiavi del sangue demoniaco, gli orchi furono liberati da Thrall e ora ricostruiscono il loro onore nella terra rossa di Durotar.",body:["Gli orchi arrivarono su Azeroth da Draenor come l\u2019Orda, spinti dal sangue demoniaco e dagli stregoni di Gul'dan. Sconfitti nella Seconda Guerra, deperirono nei campi di internamento finch\xe9 Thrall, figlio del capo dei Lupi Bianchi Durotan, non li liber\xf2 e non restaur\xf2 le usanze sciamaniche dei loro antenati.","Dopo la Terza Guerra Thrall condusse il suo popolo a Kalimdor e fond\xf2 Durotar con la sua capitale, Orgrimmar, da cui il Capoguerra governa ora un\u2019Orda condivisa con i tauren, i troll Lanciascura e i Reietti. Gli orchi sono fieri, diretti e ferocemente leali, ma il loro passato sanguinoso sopravvive nei cultisti della Lama Ardente di Durotar e nel clan Roccianera, che non si un\xec mai a Thrall. I nuovi orchi iniziano nella Valle delle Sfide. In Forever gli orchi possono anche diventare maghi."]},"race:tauren":{title:"Tauren",summary:"Gentili giganti delle pianure che onorano la Madre Terra, i tauren hanno trovato una casa a Mulgore e si sono uniti all\u2019Orda per gratitudine.",body:["I tauren sono imponenti nomadi pacifici che onorano la Madre Terra e percorrono le pianure di Kalimdor da tempo immemorabile. Negli anni della Terza Guerra erano braccati dai centauri, finch\xe9 l\u2019Orda di Thrall, appena arrivata, non aiut\xf2 il popolo di Cairne Zoccolo Sanguinario a raggiungere la sicurezza di Mulgore.","Cairne un\xec molte trib\xf9 disperse e fond\xf2 Picco del Tuono su grandi altipiani che sovrastano le praterie di Mulgore, e i tauren si unirono all\u2019Orda per gratitudine e rispetto. I loro druidi impararono dallo stesso Malfurion Grantempesta, e i loro sciamani e cacciatori tengono vive antiche tradizioni. Trib\xf9 rivali come i Grimtotem, che mal sopportano il legame con gli orchi, restano una preoccupazione costante. I giovani tauren iniziano a Campo Narache, a Mulgore."]},"race:troll":{title:"Troll",summary:"Eredi di imperi caduti, la maggior parte dei troll odia ancora le altre razze; la trib\xf9 Lanciascura, invece, ha giurato fedelt\xe0 a Thrall e all\u2019Orda.",body:["Un tempo i troll governavano vasti imperi: i Gurubashi nelle giungle del sud, gli Amani nelle foreste del nord e gli Zandalari, che si definiscono i primi di tutti i troll. Le guerre contro gli Elfi della Notte, gli Alti Elfi e gli umani spezzarono quegli imperi, e la maggior parte delle trib\xf9 nutre ancora antichi odi e prega i loa, gli dei spirituali dei loro antenati.","La trib\xf9 Lanciascura \xe8 diversa. Cacciati da Rovotorto da trib\xf9 rivali, i Lanciascura combattevano per la loro isola natale quando giunse la flotta di Thrall, sballottata dalla tempesta; il loro capo Sen'jin mor\xec l\xec e suo figlio Vol'jin giur\xf2 la trib\xf9 all\u2019Orda. Si stabilirono sulle Isole dell\u2019Eco, al largo di Durotar, ma la magia oscura dello stregone Zalazane li ha spinti fino al Villaggio di Sen'jin, sulla terraferma. In Forever i Darkspear Raiders si contendono anche le Darkspear Islands al largo di Acquemorte, e i troll possono diventare stregoni."]},"race:undead":{title:"Non Morti",summary:"Vittime della piaga risorte che si sono liberate dal Re dei Lich, i Reietti governano Sepulcra sotto le rovine di Lordaeron e non si fidano di nessuno.",body:["I Reietti erano un tempo cittadini di Lordaeron, uccisi dalla piaga e rialzati dal Flagello, che riacquistarono il libero arbitrio quando il potere del Re dei Lich vacill\xf2. Guidati dalla regina banshee Sylvanas Ventolesto, rivendicarono le rovine della capitale di Lordaeron e fecero di Sepulcra, sotto di esse, la loro casa. Le loro terre, le Radure di Tirisfal e la Selvargentea, sono contese dal Flagello e dalla Crociata Scarlatta.","I Reietti si sono uniti all\u2019Orda come alleati di necessit\xe0; pochi tra i vivi si fidano di loro, e il lavoro segreto della Societ\xe0 Reale degli Speziali su una nuova piaga d\xe0 ai loro alleati buone ragioni. I nuovi Reietti risorgono a Deathknell, nelle Radure di Tirisfal. Forever aggiunge la spedizione Ruins of Lordaeron, in cui i Reietti cercano di riconquistare la citt\xe0 distrutta sopra Sepulcra, e consente i paladini Reietti, un abbinamento che le fonti usate qui non spiegano ancora."],unknowns:["Le fonti usate da questa guida non spiegano come siano nati i paladini Reietti in Forever."]}}},1773,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"zones1",{enumerable:!0,get:function(){return o}});const o={"zone:dun-morogh":{title:"Dun Morogh",summary:"Valli innevate attorno a Forgiardente, patria dei nani e degli gnomi che hanno perso la loro citt\xe0.",body:["Circondata dalle vette di Khaz Modan, Dun Morogh \xe8 una terra di nevai, laghi ghiacciati e torri di guardia naniche. Il suo cuore \xe8 Forgiardente, la citt\xe0 di montagna del clan Barbabronzea sotto re Magni, mentre giovani nani e gnomi impugnano le armi per la prima volta nella riparata valle di Coldridge e attorno al villaggio birraio di Kharanos. I troll Frostmane e i trogg scavatori infestano le valli.","A ovest si trova Gnomeregan, la meraviglia dell\u2019ingegneria gnomica, perduta quando i trogg sono sbucati dal sottosuolo e la disperata ondata di radiazioni scatenata dai difensori ha avvelenato la citt\xe0. I suoi sopravvissuti vivono ora come ospiti a Forgiardente. In Forever, qualcuno ha violato le tombe reali della Hall of Thanes sotto la citt\xe0, e si sospetta di intrusi Ferroscuro."]},"zone:durotar":{title:"Durotar",summary:"L\u2019aspra costa rossa che Thrall chiam\xf2 come suo padre e dove gli orchi costruirono Orgrimmar.",body:["Quando Thrall condusse l\u2019Orda a Kalimdor, rivendic\xf2 questa striscia di costa orientale spaccata dal sole e la chiam\xf2 Durotar, dal nome di suo padre Durotan. La terra rossa e i canyon pietrosi ricordavano Draenor agli orchi. Scacciarono i verrospini dalla regione e innalzarono Orgrimmar, chiamata cos\xec in onore di Orgrim Martelfato, in una conca montana a nord.","I giovani orchi e troll mettono alla prova il loro valore nella Valle delle Sfide prima di proseguire verso Razor Hill. Sulla costa, i troll Lanciascura occupano il Villaggio di Sen'jin da quando lo stregone Zalazane ha reso schiavi i loro simili sulle Isole dell\u2019Eco, e soldati di Kul Tiras resistono al Forte Tiragarde. I cultisti della Lama Ardente si annidano sulle colline, e il loro culto gemello, la Searing Blade, si nasconde nella Voragine Infuocata, sotto la capitale."]},"zone:elwynn-forest":{title:"Foresta di Elwynn",summary:"Il verde cuore del regno di Roccavento, dove molti eroi umani muovono i primi passi.",body:["La Foresta di Elwynn \xe8 il cuore placido del regno di Roccavento: querceti, fattorie e laghi attorno alle mura bianche della citt\xe0 di Roccavento, ricostruita dopo che l\u2019Orda l\u2019aveva rasa al suolo nella Prima Guerra. I novizi si addestrano all\u2019Abbazia di Contea del Nord, e i viaggiatori riposano alla Locanda Orgoglio del Leone, a Borgodoro.","La pace \xe8 pi\xf9 fragile di quanto sembri. I coboldi hanno preso le miniere, gli gnoll Riverpaw razziano le fattorie a ovest, i murloc affollano i laghi e i banditi Defias si diffondono dalle vicine Marche Occidentali. Nella capitale stessa, le Segrete sono cadute in mano a una rivolta di detenuti Defias."]},"zone:mulgore":{title:"Mulgore",summary:"Le pianure spazzate dal vento dei tauren, coronate dagli altipiani di Picco del Tuono.",body:["Mulgore \xe8 la prateria ancestrale dei tauren, una conca verde di pianure e altipiani cinta da montagne, con un solo passo a est verso le Savane. Per generazioni i tauren nomadi furono braccati dai centauri, finch\xe9 l\u2019Orda di Thrall non aiut\xf2 il Gran Capo Cairne Zoccolo Sanguinario a riportare a casa il suo popolo. Qui eressero i loro primi insediamenti duraturi: il Villaggio di Zoccolo Sanguinario e la capitale, Picco del Tuono, costruita in cima ad altissimi altipiani collegati da ponti di corda.","I giovani tauren si addestrano a Campo Narache, sul Red Cloud Mesa, mentre gnoll, verrospini e cercatori della Venture Company disturbano le pianure. In Forever, gli Skyborne dell\u2019Orda arrivano in aeronave da Zephras Isle allo Skywatcher Plateau."]},"zone:teldrassil":{title:"Teldrassil",summary:"Il nuovo Albero del Mondo degli Elfi della Notte al largo della costa settentrionale di Kalimdor, con Darnassus tra i suoi rami.",body:["Dopo che la Terza Guerra era costata loro l\u2019immortalit\xe0, i druidi degli Elfi della Notte fecero crescere un nuovo Albero del Mondo al largo della costa settentrionale di Kalimdor. Lo chiamarono Teldrassil, \u201ccorona della terra\u201d, e costruirono Darnassus tra i suoi rami, una citt\xe0 di templi illuminati dalla luna dove l\u2019Alta Sacerdotessa Tyrande Soffiabrezza guida il suo popolo.","L\u2019albero fu piantato senza la benedizione degli Aspetti dei Draghi, e la sua crescita non \xe8 stata pura. La corruzione si \xe8 insinuata nella sua fauna e ha reso selvaggi i furbolg Gnarlpine. I novizi degli Elfi della Notte iniziano a Shadowglen, e le imbarcazioni del Villaggio di Rut'theran, tra le radici, collegano l\u2019isola a Rivafosca."]},"zone:tirisfal-glades":{title:"Radure di Tirisfal",summary:"Cupe radure attorno alle rovine della capitale di Lordaeron, oggi il cuore dei Reietti.",body:["Nelle Radure di Tirisfal sorgeva un tempo la capitale di Lordaeron, e il Consiglio di Tirisfal, l\u2019ordine che sceglieva i Guardiani, prese il nome dalle sue riunioni segrete su queste quiete colline. La piaga e la caduta del regno hanno lasciato la terra sotto un cielo verde e malsano. Sotto il palazzo in rovina, i Reietti di Sylvanas Ventolesto hanno fatto di Sepulcra la loro casa; i loro morti appena risorti si risvegliano a Deathknell e si radunano nel villaggio di Brill.","I nemici premono da ogni lato: i resti del Flagello infestano le fattorie, e i fanatici della Crociata Scarlatta occupano il Monastero Scarlatto a nord-est. In Forever, i Reietti cercano di riconquistare la citt\xe0 distrutta sopra di loro, dove si dice che un negromante stia accumulando potere nelle Ruins of Lordaeron."]},"zone:zephras-isle":{title:"Zephras Isle",summary:"Un\u2019isola volante in Skywall, il Piano Elementale dell\u2019Aria, e la zona iniziale degli Skyborne di Forever.",body:["Zephras Isle \xe8 la zona iniziale degli Skyborne, la razza giocabile nuova di World of Warcraft: Forever, sbloccata con lo Skyborne Heroic o Epic Pack facoltativo. L\u2019isola fluttua in Skywall, il Piano Elementale dell\u2019Aria, dove un tempo gli Skyborne la condividevano con gli elementali dell\u2019aria. Quegli elementali sono scomparsi diversi secoli fa, e la magia che tiene sospesa l\u2019isola si sta indebolendo da allora. Con loro si \xe8 perso il contatto con le altre isole degli Skyborne, Anvilas e Siroccas.","Ora quelle isole stanno crollando, i profughi fuggono verso Zephras e la stessa Zephras ha cominciato a sgretolarsi. L\u2019Alta Anziana Talaanis Shadowsong governa dalla citt\xe0 di Valanaar, i cui moli aerei mandano aeronavi a Dalaran, sulle Montagne d\u2019Alterac, per l\u2019Alleanza e allo Skywatcher Plateau, a Mulgore, per l\u2019Orda."],unknowns:["Le fonti usate da questa guida non spiegano perch\xe9 gli elementali dell\u2019aria siano scomparsi.","L\u2019origine profonda degli Skyborne e dei loro ordini non \xe8 ancora trattata dalle fonti di questa guida.","Gli antichi signori dell\u2019isola, gli Shal\u2019nan, vengono solo nominati, non descritti."]},"zone:darkshore":{title:"Rivafosca",summary:"Una costa nebbiosa e disseminata di rovine, che gli Elfi della Notte sorvegliano dal porto di Auberdine.",body:["Rivafosca \xe8 una lunga striscia della costa nord-occidentale di Kalimdor, scurita dalla pioggia e disseminata delle rovine cadenti di citt\xe0 kaldorei di prima della Grande Frattura. Gli Elfi della Notte la rivendicano come parte del loro nuovo regno, e le Sentinelle pattugliano la strada che dal porto di Auberdine scende a sud verso Valtetra.","Il pericolo si annida lontano dalla strada: spettri si aggirano tra le antiche rovine, naga e murloc battono le spiagge, i furbolg inselvatichiscono nei boschi e i cultisti del Martello del Crepuscolo e del Dark Strand si nascondono sulle colline. Le navi di Auberdine salpano per Teldrassil, per il Porto di Menethil e, in Forever, per Roccavento; una nuova rotta di Forever arriva inoltre da Southshore."]},"zone:loch-modan":{title:"Loch Modan",summary:"Una valle degli altipiani nanici il cui grande lago \xe8 trattenuto dalla Stonewrought Dam.",body:["A est di Dun Morogh si trova Loch Modan, una fresca valle d\u2019altura di pini e betulle attorno a un grande lago trattenuto dalla Stonewrought Dam, una delle meraviglie dell\u2019ingegneria nanica. Pochi ricordano che a progettarla fu un architetto Ferroscuro. Il villaggio di Thelsamar sorveglia la strada, e la Stazione di Algaz controlla il passo che porta a nord, verso le Wetlands.","La valle ricorda la Seconda Guerra, quando l\u2019Orda la travolse prima che i nani di Forgiardente la respingessero. Oggi il pericolo sale dal basso: scavi come quello di Ironband hanno risvegliato i trogg dalle profondit\xe0, gli ogre Mo'grosh occupano le colline e i nani Ferroscuro attaccano la diga stessa."]},"zone:silverpine-forest":{title:"Selvargentea",summary:"Una pineta infestata sulla costa occidentale di Lordaeron, contesa tra Reietti, worgen e gli ultimi umani della regione.",body:["La Selvargentea si estende lungo la frastagliata costa occidentale di Lordaeron, con i suoi pini dalla corteccia argentata ormai malati e avvolti nella nebbia. I Reietti controllano il nord dal Sepolcro, mentre i sopravvissuti umani e i maghi inviati da Dalaran si aggrappano ad Ambermill e al sud. Pi\xf9 in l\xe0, Gilneas si \xe8 chiusa dietro il Greymane Wall.","L\u2019ombra pi\xf9 profonda della foresta \xe8 il Forte Zannascura, un tempo il castello del barone Silverlaine. Durante la Terza Guerra, l\u2019arcimago di Dalaran Arugal evoc\xf2 dei worgen per combattere il Flagello, ne perse il controllo e impazz\xec; ora chiama quelle bestie i suoi figli. La sua maledizione ha raggiunto il vicino villaggio di Pyrewood, i cui abitanti si trasformano in worgen al calar della notte."]},"zone:westfall":{title:"Marche Occidentali",summary:"Il granaio abbandonato di Roccavento, oggi territorio della Confraternita Defias.",body:["Le Marche Occidentali erano un tempo il granaio di Roccavento, una costa di campi dorati e mulini a vento. Dalla Seconda Guerra gran parte della regione giace incolta, e il regno non ha avuto n\xe9 denaro n\xe9 soldati da dedicarle. In quel vuoto si \xe8 inserita la Confraternita Defias: i muratori che ricostruirono Roccavento e divennero fuorilegge dopo che i nobili si rifiutarono di pagarli, guidati da Edwin VanCleef.","I Defias dominano il villaggio in rovina di Moonbrook e nascondono un cantiere navale nelle Miniere della Morte, sotto di esso, mentre gnoll e golem mietitori impazziti assalgono le fattorie rimaste. Solo la Milizia del Popolo, radunata da Gryan Stoutmantle al Colle della Sentinella, li contrasta ancora."]},"zone:barrens":{title:"Savane",summary:"Una vasta savana nel cuore di Kalimdor, attraversata dalla Via dell\u2019Oro e controllata soprattutto dall\u2019Orda.",body:["Le Savane sono una distesa sconfinata di alberi spinosi, oasi e letti di fiumi in secca nel cuore di Kalimdor. Prima della Grande Frattura qui sorgevano citt\xe0 degli Elfi della Notte; oggi l\u2019Orda controlla la regione dal Crocevia e da Campo Taurajo, i goblin di Ratchet commerciano via mare con la Baia del Bottino e i soldati dell\u2019Alleanza montano la guardia da Northwatch Hold. In Forever, la Durotar Supply and Logistics commercia da un accampamento a ovest del Crocevia.","Centauri Kolkar, verrospini e arpie assaltano i viaggiatori lungo la Via dell\u2019Oro. Sotto terra si aprono tre antiche ferite: le Caverne dei Lamenti, dove il sogno di un druido si \xe8 trasformato in incubo, e le spinose tane di Razorfen Kraul e Razorfen Downs, sacre ai verrospini."]},"zone:redridge-mountains":{title:"Montagne Crestarossa",summary:"Colline rosse e un lago tranquillo a est di Elwynn, dove Lakeshire resiste a gnoll e orchi Roccianera.",body:["A est di Elwynn si innalzano le Montagne Crestarossa, una terra di pietra rossa, olmi alti e fiumi impetuosi che fornisce legname, pesce e grano a Roccavento. Il suo centro principale, Lakeshire, sorge sulla riva del Lake Everstill, e il crocevia di Three Corners lo collega a Elwynn e a Duskwood.","Qui la pace \xe8 fragile. Gli gnoll di Crestarossa razziano le fattorie, e gli orchi Roccianera giunti dalle Steppe Ardenti hanno preso la Stonewatch Keep e si accampano nella Render's Valley. Molto tempo fa i nani Ferroscuro costruirono un regno su queste montagne, finch\xe9 l\u2019evocazione di Ragnaros da parte di Thaurissan non bruci\xf2 le terre a nord. In Forever, l\u2019Azeroth Commerce Authority commercia a Three Corners, e alcuni passi conducono a est, verso le Riverglades."]},"zone:stonetalon-mountains":{title:"Stonetalon Mountains",summary:"Vette impervie a ovest delle Savane, sacre a Elfi della Notte e tauren e sfregiate dal disboscamento dei goblin.",body:["Le Stonetalon Mountains si innalzano a ovest delle Savane; sono la patria ancestrale delle arpie, anche se i loro stormi si sono poi diffusi ben oltre. La vetta pi\xf9 alta, lo Stonetalon Peak, \xe8 sacra sia agli Elfi della Notte sia ai tauren; gli Elfi della Notte custodiscono un tumulo e una radura vicino alla cima, i tauren occupano il Sun Rock Retreat sulle alture centrali e i troll Lanciascura si accampano a Malaka'jin.","Il danno maggiore lo ha fatto la Venture Company: i suoi goblin hanno spogliato il Windshear Crag di quasi tutti gli alberi, soffocando l\u2019aria di fuliggine e inquinando l\u2019acqua di petrolio. I tauren Grimtotem, i coboldi e le bestie pericolose del Charred Vale non rendono pi\xf9 sicure le strade."]},"zone:ashenvale":{title:"Valtetra",summary:"La foresta ancestrale degli Elfi della Notte, dove cominci\xf2 la guerra con l\u2019Orda per il suo legname.",body:["Valtetra \xe8 la foresta ancestrale degli Elfi della Notte, un bosco profondo di ombre violacee e alberi antichissimi che si estende dallo Zoram Strand fino ai confini delle Savane. I Kaldorei occupano Astranaar e una serie di avamposti, e le Sentinelle difendono con ferocia i loro boschetti.","Durante la Terza Guerra, gli orchi Cantaguerra di Grom Malogrido penetrarono in questi boschi, bevvero di nuovo il sangue demoniaco e uccisero il semidio Cenarius; Grom mor\xec in seguito uccidendo il signore degli abissi Mannoroth nel luogo oggi chiamato Demon Fall Canyon. Gli orchi continuano a disboscare l\u2019est dallo Splintertree Post e dagli accampamenti Cantaguerra, e l\u2019antica contesa cova ancora. I satiri infestano le rovine, e sulla costa si trovano gli Abissi Neri, un tempio di Elune sommerso."]},"zone:duskwood":{title:"Duskwood",summary:"Un angolo un tempo luminoso di Elwynn inghiottito da una notte senza fine, difeso dalla gente ostinata di Darkshire.",body:["Duskwood era un tempo la parte meridionale della Foresta di Elwynn, dove sorgevano i villaggi oggi chiamati Darkshire e Raven Hill. Poi cal\xf2 un\u2019ombra che non si \xe8 mai pi\xf9 sollevata, legata al destino della Falce di Elune degli Elfi della Notte. Sotto il suo crepuscolo infinito gli alberi divennero contorti, e worgen, non-morti e ogre del Deadwind Pass cominciarono ad aggirarsi nei dintorni.","Roccavento ha in gran parte lasciato la regione a s\xe9 stessa. La Guardia Notturna di Darkshire sorveglia la strada principale, il cimitero di Raven Hill si riempie di morti senza pace e, nel profondo del bosco, il Twilight Grove custodisce un grande albero e un portale verso il Sogno di Smeraldo."]},"zone:wetlands":{title:"Wetlands",summary:"Paludi grigie e fradice di pioggia che sorvegliano la strada tra Khaz Modan e Lordaeron.",body:["Le Wetlands sono una palude fredda e avvolta nella nebbia tra le montagne di Khaz Modan e il mare. Un tempo la regione era costellata di roccaforti naniche; la guerra ne ha distrutte quasi tutte. Il Porto di Menethil \xe8 qui l\u2019ancora dell\u2019Alleanza, un porto le cui navi salpano per Theramore e, in Forever, fino a Southshore. I viaggiatori arrivano dall\u2019assediata Dun Algaz o dal danneggiato Thandol Span.","A est incombe Grim Batol, la citt\xe0 maledetta dei Granmartello dove il clan Fauci di Drago tenne prigionieri i draghi rossi durante la Seconda Guerra; rinnegati Fauci di Drago vagano ancora per la palude, e i nani Ferroscuro occupano Dun Modr. In Forever, una nebbia strana e lampi di luce sopra il Whelgar's Excavation Site conducono a una spedizione piena di costrutti dei Titani."]},"zone:hillsbrad-foothills":{title:"Colline di Hillsbrad",summary:"Verdi colline dove Southshore e il Mulino di Tarren si fronteggiano vicino alle rovine di Durnholde.",body:["Le verdi e fertili colline di Hillsbrad si trovano appena a sud dell\u2019antico regno di Alterac. Qui si fronteggiano due centri: Southshore, dell\u2019Alleanza, sulla costa, e l\u2019avamposto dei Reietti del Mulino di Tarren, sulle colline, e la loro faida tiene insanguinati i campi. Murloc e il Sindacato aggravano i problemi.","Su un\u2019altura a est sorge la fortezza di Durnholde, un tempo quartier generale dei campi di internamento degli orchi, dove Lord Aedelas Blackmoore crebbe il giovane Thrall come gladiatore prima che fuggisse per liberare il suo popolo; oggi il Sindacato ne occupa le rovine. In Forever, le missioni che aprono la strada alla City of Dalaran iniziano in entrambi i centri, e le navi fanno scalo a Southshore."]},"zone:thousand-needles":{title:"Millepicchi",summary:"Un canyon di guglie di pietra e distese di sale, dove tauren, centauri e goblin appassionati di corse condividono un terreno instabile.",body:["Millepicchi \xe8 un vasto canyon arido di altissimi altipiani di pietra nel sud di Kalimdor, raggiungibile dalle Savane attraverso il Grande Montacarichi. I tauren del Freewind Post vivono in cima agli altipiani, mentre i Grimtotem, un clan tauren ostile a Cairne Zoccolo Sanguinario, occupano il Darkcloud Pinnacle. I centauri Galak percorrono il fondo del canyon e le arpie nidificano tra le guglie.","A est il canyon si apre sugli Shimmering Flats, una distesa di sale accecante dove ingegneri goblin e gnomi fanno correre le loro macchine sulla Mirage Raceway."]},"zone:alterac-mountains":{title:"Montagne d\u2019Alterac",summary:"Il regno spezzato di Alterac e le rovine schermate di Dalaran, contesi da ogre e dal Sindacato.",body:["Le Montagne d\u2019Alterac erano un tempo il regno di Alterac, il cui signore, Aiden Perenolde, trad\xec l\u2019Alleanza a favore dell\u2019Orda durante la Seconda Guerra. Il regno fu sciolto; oggi gli ogre Crushridge si sono insediati tra le rovine della citt\xe0 di Alterac, e il Sindacato di Aliden Perenolde, erede della casata caduta in disgrazia, governa Strahnbrad. I ladri di Ravenholdt fanno storia a s\xe9 sulle colline.","Presso il Lago Lordamere giacciono i resti di Dalaran, la citt\xe0 dei maghi che Archimonde distrusse nella Terza Guerra. Il Kirin Tor la sta ricostruendo dietro una barriera magica. In Forever quella barriera \xe8 caduta e la citt\xe0 trabocca di caos arcano; \xe8 anche qui che gli Skyborne dell\u2019Alleanza arrivano in aeronave da Zephras Isle."]},"zone:arathi-highlands":{title:"Altipiani di Arathi",summary:"L\u2019antico cuore di Arathor, dove Stromgarde giace in rovina e tre fazioni si contendono ci\xf2 che resta.",body:["Gli Altipiani di Arathi erano il cuore di Arathor, il primo impero umano, fondato da re Thoradin con capitale a Strom. La sua erede, Stromgarde, giace oggi in gran parte in rovina a sud-ovest, dove i difensori del principe Galen Trollbane combattono una guerriglia a tre contro il Sindacato e gli ogre Boulderfist. Il Muro di Thoradin segna ancora l\u2019antico confine a ovest.","L\u2019Alleanza si raduna a Refuge Pointe. L\u2019Orda occupa Hammerfall, un ex campo di internamento chiamato cos\xec in onore del Capoguerra Orgrim Martelfato, caduto mentre liberava il suo popolo. I troll Witherbark infestano le colline, e il Thandol Span collega gli altipiani alle Wetlands."]},"zone:desolace":{title:"Desolanda",summary:"Una landa grigia coperta di cenere, piena di ossa di kodo e di trib\xf9 di centauri in guerra.",body:["Desolanda \xe8 una distesa desolata di cenere grigia, alberi morti e teschi di antichi kodo, che vengono a morire nel Cimitero dei Kodo. Le rovine delle citt\xe0 degli Highborne, distrutte dalla Grande Frattura, si sgretolano sulle sue colline, e demoni e satiri si radunano ancora dove persiste l\u2019antica magia.","\xc8 la patria dei centauri, nati nelle caverne di Maraudon dall\u2019unione di Zaetar, figlio di Cenarius, e della principessa della terra Theradras. Le loro quattro trib\xf9, i Kolkar, i Gelkis, i Magram e i Maraudine, si combattono tra loro con la stessa ferocia con cui combattono gli stranieri. L\u2019Alleanza occupa il Nijel's Point e l\u2019Orda lo Shadowprey Village."]}}},1774,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"zones2",{enumerable:!0,get:function(){return o}});const o={"zone:stranglethorn-vale":{title:"Rovotorto",summary:"Una giungla afosa di citt\xe0 troll cadute, cacciatori, pirati e il porto goblin della Baia del Bottino.",body:["Rovotorto era il cuore dei troll Gurubashi, il cui impero un tempo dominava la giungla da Zul'Gurub. Le loro citt\xe0 di pietra oggi si sgretolano sotto i rampicanti, ancora infestate dai troll della giungla, mentre ogre, naga e i famigerati rovi strangolatori della valle rendono pericoloso ogni sentiero. I cacciatori accorrono alla spedizione di Nesingwary, l\u2019Orda occupa il Campo Base di Grom'gol e i ribelli dell\u2019Alleanza si accampano a nord.","All\u2019estremit\xe0 meridionale, i goblin della Baia del Bottino gestiscono un porto senza legge accanto ai pirati dei Blackwater Raiders, e combattenti di ogni razza si incontrano nella vecchia Arena dei Gurubashi. In Forever, antiche rovine troll sono riemerse dal mare a ovest di Grom'gol: la Drowned City, ora percorsa da troll e naga."]},"zone:badlands":{title:"Maleterre",summary:"Un deserto screpolato di canyon dove i nani scavano alla ricerca dei segreti dei Titani e l\u2019Orda sorveglia da Kargath.",body:["Le Maleterre sono un deserto screpolato e cotto dal sole, fatto di macigni e canyon tortuosi, nel sud di Khaz Modan. I cercatori di Forgiardente lo setacciano in cerca di reliquie dei Titani, attirati da Uldaman, un\u2019enorme camera sepolta che ha rivelato i primi indizi sull\u2019origine dei nani come esseri di pietra vivente. Trogg liberati da un lungo sonno massacrarono la prima spedizione e ora ne difendono le sale.","I nani Ferroscuro occupano l\u2019Angor Fortress, gli ogre Dustbelcher si accampano in tutta la landa e la progenie dei draghi neri nidifica nella Lethlor Ravine. L\u2019Orda sorveglia dall\u2019avamposto di Kargath, vicino alla strada per la Gola Rovente."]},"zone:dustwallow-marsh":{title:"Acquemorte",summary:"Una palude fumante che nasconde Theramore, il covo di Onyxia e la prigione a lungo sigillata dell\u2019isola di Alcaz.",body:["Acquemorte \xe8 una palude antica e sempre umida sulla costa orientale di Kalimdor, brulicante di crocolischi, raptor e murloc. Al largo della costa sorge l\u2019Isola di Theramore, la citt\xe0-fortezza che Jaina Marefiero fond\xf2 per i sopravvissuti che l\u2019avevano seguita a ovest; l\u2019Orda risponde dal villaggio di Brackenwall, ai margini della palude. A sud, i draghi neri infestano il Wyrmbog attorno al covo di Onyxia.","Da tempo circolano voci sull\u2019isola di Alcaz, la cui prigione avrebbe ospitato prigionieri di alto rango, perfino re Varian Wrynn. In Forever le sue porte si aprono finalmente e rivelano la Confraternita Defias e i naga in guerra al suo interno."]},"zone:riverglades":{title:"Riverglades",summary:"Una terra di fiumi contesa nel sud-est di Khaz Modan, nuova in Forever, dove i cavalieri di Farholde combattono ancora una guerra che Roccavento si \xe8 lasciata alle spalle.",body:["Le Riverglades si trovano a est delle Maleterre e delle Steppe Ardenti e un tempo appartenevano al regno di Roccavento. Nella Prima Guerra l\u2019Orda saccheggi\xf2 il villaggio di Sunnyglade e ne rese schiavi gli abitanti. Alcune famiglie fuggirono e fondarono Windstead, mentre i cavalieri che liberarono i prigionieri fondarono Meadowsbrook e poi fortificarono un\u2019isola costiera con il nome di Farholde. Credendo la regione perduta, Roccavento si dedic\xf2 ad altre preoccupazioni.","Verso la fine della Seconda Guerra, ogre del Martello del Crepuscolo e orchi Stormreaver in fuga dalla Tomba di Sargeras si rifugiarono qui, e anni di incursioni culminarono nell\u2019assedio di Farholde. Nell\u2019anno 25, la Brotherhood of the Horse del cavaliere comandante Demar Brant combatte ancora, il Martello del Crepuscolo occupa la Sunnyglade in rovina e gli ogre Bolder'ok si sono uniti all\u2019Orda."],unknowns:["Le fonti non dicono chi guidi le forze dell\u2019Orda a Rog'mar e a Bolder'ok.","Che Cho\u2019gall sia giunto nella regione dopo la Seconda Guerra \xe8 solo una voce.","Il significato dei canti che si sentono dalla Krol\u2019dok Stronghold dopo il tramonto resta aperto."]},"zone:swamp-of-sorrows":{title:"Palude del Dolore",summary:"Una palude salmastra dove i draghi verdi custodiscono il tempio sommerso di Atal'Hakkar e l\u2019Orda occupa Stonard.",body:["La Palude del Dolore \xe8 un acquitrino stagnante di salici piangenti e acqua salmastra nel sud dei Regni Orientali, vicino al punto in cui si apr\xec per la prima volta il Portale Oscuro. L\u2019Orda ha sfruttato al meglio la sua distanza da Roccavento: la citt\xe0 orchesca di Stonard \xe8 qui la sua roccaforte. Crocolischi, bestie palustri e un gruppo di draenei esiliati condividono le acque torbide.","Nel cuore della palude si trova il Tempio di Atal'Hakkar, il santuario sommerso dove i sacerdoti Atal'ai tentarono un tempo di evocare il loro dio del sangue, Hakkar. Ora lo custodiscono i draghi verdi dell\u2019Aspetto Ysera, che avvertono che un orrore vi si agita ancora."]},"zone:feralas":{title:"Feralas",summary:"Una foresta rigogliosa nutrita dalle piogge, di alberi giganti, rovine occupate dagli ogre e l\u2019antica citt\xe0 degli Highborne, Eldre'Thalas.",body:["Feralas \xe8 una foresta rigogliosa e zuppa di pioggia, di alberi giganti, sulla costa sud-occidentale di Kalimdor, un tempo parte dell\u2019antico regno degli Elfi della Notte. La sua rovina pi\xf9 grande \xe8 Eldre'Thalas, oggi chiamata Maglio Infausto, dove gli Shen'dralar, Highborne sopravvissuti alla Grande Frattura, vissero isolati per diecimila anni. Gli ogre Gordunni hanno invaso le antiche rovine elfiche e diffuso la loro corruzione in tutta la regione.","Le Sentinelle della Feathermoon Stronghold sorvegliano la costa dall\u2019isola di Sardor, mentre i tauren di Campo Mojache danno la caccia ai rinnegati Grimtotem per l\u2019Orda. I naga controllano le isole occidentali, sono comparsi alveari di silitidi e i draghi verdi custodiscono il Dream Bough, un portale verso il Sogno di Smeraldo."]},"zone:hinterlands":{title:"Entroterre",summary:"Selvagge colline settentrionali di cavalcatori di grifoni e troll delle foreste, patria dei nani Granmartello ad Aerie Peak.",body:["Gli Entroterre sono un altopiano impervio e boscoso nel nord di Lordaeron. Dopo la Guerra dei Tre Martelli, i nani Granmartello abbandonarono la maledetta Grim Batol e si stabilirono qui, ad Aerie Peak, dove domano i grifoni selvatici della regione e restano fedeli alleati dell\u2019Alleanza. Qualche Alto Elfo presidia ancora la Quel'Danil Lodge.","Le colline appartengono altrettanto ai troll delle foreste. La trib\xf9 Revantusk si \xe8 schierata con l\u2019Orda di Thrall, mentre i Vilebranch governano la grande citt\xe0-tempio di Jintha'Alor e i Witherbark si annidano attorno a Shadra'Alor. A nord, l\u2019antico albero Seradane custodisce un portale verso il Sogno di Smeraldo, sorvegliato dai draghi verdi."]},"zone:tanaris":{title:"Tanaris",summary:"Un mare di dune governato da Gadgetzan, che nasconde le Caverne del Tempo e la citt\xe0 troll di Zul'Farrak.",body:["Tanaris \xe8 un deserto senza fine di dune e tempeste di sabbia nel sud-est di Kalimdor. I goblin dello Steamwheedle Cartel lo gestiscono da Gadgetzan e dallo Steamwheedle Port, mantenendo una fragile neutralit\xe0 mentre i banditi Wastewander, i pirati dei Mari del Sud e gli ogre Dunemaul assaltano i viaggiatori.","Il deserto nasconde poteri pi\xf9 antichi. Nelle Caverne del Tempo lo stormo bronzeo di Nozdormu veglia sul corso della storia; lontano a sud si trovano le rovine dei Titani di Uldum; e i troll delle sabbie di Zul'Farrak difendono la loro citt\xe0 fortificata a nord-ovest. In Forever, una nave dallo Steamwheedle Port collega il deserto a Powderfuse Port, nelle Riverglades."]},"zone:searing-gorge":{title:"Gola Rovente",summary:"Una fossa riarsa di miniere dei Ferroscuro e lavoro schiavile, annerita dall\u2019evocazione di Ragnaros.",body:["La Gola Rovente \xe8 una terra annerita di cenere e roccia fusa nel sud di Khaz Modan. Deve le sue cicatrici alla stessa catastrofe che bruci\xf2 le Steppe Ardenti: l\u2019evocazione di Ragnaros da parte del thane stregone Thaurissan, che pose fine alla Guerra dei Tre Martelli. Oggi la dominano i nani Ferroscuro, che costringono gli schiavi a estrarre minerale nella grande spaccatura del Calderone.","Non tutti i Ferroscuro servono il Signore del Fuoco. La Confraternita del Torio, maestri fabbri che si sono separati dal loro clan, commercia con gli stranieri dal Presidio del Torio. A sud incombe il Massiccio Roccianera, con l\u2019impero dei Ferroscuro nelle sue profondit\xe0 e il bastione, in alto, in mano a orchi e draghi neri."]},"zone:azshara":{title:"Azshara",summary:"Una costa di eterno autunno sopra le rovine sommerse della capitale della regina Azshara.",body:["Azshara \xe8 una costa frastagliata di eterno autunno nel nord-est di Kalimdor, con alberi che ardono di rosso e d\u2019oro. Qui sorgeva Zin-Azshari, la pi\xf9 grande citt\xe0 degli antichi Elfi della Notte, finch\xe9 la Grande Frattura non ne scagli\xf2 la maggior parte in mare. Terrazze in rovina restano aggrappate alle scogliere, infestate dagli spiriti inquieti degli Highborne; naga e satiri si aggirano sulla riva, e l\u2019Alleanza al Talrendis Point e l\u2019Orda a Valormok mantengono piccoli accampamenti.","In Forever, un portale di Azshara sigillato da tempo si apre su Blackmaw Hold, una grande citt\xe0 furbolg il cui clan combatte una corruzione che si diffonde nei suoi boschetti e nelle sue gallerie. Le sue profondit\xe0 si collegano alle Barrow Deeps e scendono ancora pi\xf9 in basso."]},"zone:blasted-lands":{title:"Terre Devastate",summary:"Un deserto rosso e in rovina attorno al silenzioso Portale Oscuro, sorvegliato dai maghi e dai paladini del Forte Nethergarde.",body:["Le Terre Devastate facevano un tempo parte della Palude Nera, finch\xe9 la magia che apr\xec il Portale Oscuro non le deform\xf2 in un deserto rosso di argilla screpolata. Il grande portale attraverso cui l\u2019Orda invase per la prima volta si erge ancora qui, con la sua cornice di pietra scura e silenziosa dalla sua distruzione. Il Forte Nethergarde, una fortezza di Roccavento con maghi e paladini, lo sorveglia.","Ben poco vive in questa landa riarsa oltre a scorpioni, basilischi, ogre Dreadmaul e qualche draenei esiliato. Anche i demoni vi indugiano: il signore della rovina Kazzak raduna ci\xf2 che resta della Legione Infuocata nella Tainted Scar."]},"zone:felwood":{title:"Vilbosco",summary:"Una foresta un tempo incantevole avvelenata dai demoni, dove i furbolg Timbermaw e i druidi combattono il marciume.",body:["Il Vilbosco era un tempo un paradiso di ruscelli e prati curato dagli Elfi della Notte. Nella Terza Guerra la Legione Infuocata lo corruppe con il potere del Teschio di Gul'dan, e la terra non si \xe8 mai ripresa: i suoi fiumi scorrono verdi di veleno, i suoi antichi e i suoi treant marciscono sul posto, e satiri, infernali e il Concilio dell\u2019Ombra di Jaedenar, adoratore di demoni, infestano le sue radure.","Gli Elfi della Notte della Talonbranch Glade, l\u2019Orda al Bloodvenom Post e i druidi dell\u2019Emerald Sanctuary cercano di respingere la corruzione. A nord, i Timbermaw, una delle ultime trib\xf9 di furbolg non corrotte, sorvegliano le gallerie che conducono alla Radura Lunare e a Fontefredda."]},"zone:un-goro-crater":{title:"Cratere di Un'Goro",summary:"Un cratere di giungla primordiale pieno di dinosauri, elementi viventi e silenziosi piloni dei Titani.",body:["Il Cratere di Un'Goro \xe8 una giungla primordiale e fumante sprofondata tra i deserti del sud di Kalimdor, un mondo a parte dove cacciano i diavolosauri, gli elementali sorgono dalle sorgenti calde e il Fire Plume Ridge fuma al centro. Gli esploratori si radunano al Rifugio di Marshal per studiare i suoi cristalli rossi, blu, verdi e gialli e i misteriosi piloni sulle creste del cratere, che sembrano opera dei Titani.","A sud sono comparsi i silitidi, che si diffondono dalla vicina Silithus. In Forever, un\u2019antica struttura dei Titani in alto sopra il cratere, Shaper's Terrace, si apre agli avventurieri che portano cristalli di energia raccolti in tutto Un'Goro."]},"zone:burning-steppes":{title:"Steppe Ardenti",summary:"Altipiani soffocati dalla cenere sotto il Massiccio Roccianera, in mano a orchi Roccianera, ogre Fire-Gut e draghi neri.",body:["Le Steppe Ardenti sono un altopiano in rovina di cenere, lava e pietra fumante, bruciato quando l\u2019evocazione di Ragnaros da parte di Thaurissan pose fine alla Guerra dei Tre Martelli; le rovine dell\u2019antica citt\xe0 Ferroscuro di Thaurissan sono ancora in piedi. Le steppe ospitano l\u2019unica via di terra tra Roccavento e Khaz Modan, eppure il regno le ha quasi abbandonate.","Sopra di esse incombe il Massiccio Roccianera. Il Bastione Roccianera, la grande fortezza dell\u2019Orda nella Seconda Guerra, \xe8 in mano agli orchi Roccianera e ai draghi neri al comando di Nefarian, mentre i nani Ferroscuro governano le profondit\xe0. Gli ogre Fire-Gut vagano per le pianure, e resistono soltanto l\u2019avamposto dell\u2019Alleanza della Veglia di Morgan e l\u2019accampamento dell\u2019Orda di Flame Crest."]},"zone:western-plaguelands":{title:"Terre Infette Occidentali",summary:"Le campagne devastate di Lordaeron, dove il Flagello occupa Andorhal e la tomba di Uther \xe8 l\u2019ultimo suolo consacrato.",body:["Le Terre Infette Occidentali erano un tempo tra le campagne pi\xf9 ricche di Lordaeron; oggi una nebbia grigia grava su campi malati e i non-morti vagano per fattorie abbandonate. Il villaggio in rovina di Andorhal, dove il culto di Kel'Thuzad distribu\xec il suo grano appestato, \xe8 qui la principale roccaforte del Flagello, e i calderoni della piaga avvelenano i campi attorno. Su un\u2019isola del Lago Darrowmere, Caer Darrow, la fortezza della famiglia Barov, nasconde Scholomance, una scuola di negromanzia.","La Crociata Scarlatta combatte da Hearthglen, a nord, l\u2019Alleanza dal Chillwind Camp, e i Reietti occupano il Baluardo al confine con Tirisfal. La Tomba di Uther, luogo di riposo del Portatore di Luce, \xe8 l\u2019unico luogo consacrato in cui regna la pace."]},"zone:eastern-plaguelands":{title:"Terre Infette Orientali",summary:"L\u2019angolo pi\xf9 devastato della caduta Lordaeron, governato dal Flagello dalla citt\xe0 bruciata di Stratholme.",body:["Le Terre Infette Orientali sono il resto pi\xf9 devastato del regno di Lordaeron: terra bruna e malata, alberi gonfiati fino a diventare funghi giganti e aria densa di nebbia arancione. Al centro si trova Stratholme, la citt\xe0 i cui abitanti il principe Arthas pass\xf2 a fil di spada nella Terza Guerra, oggi divisa tra il Flagello e la Crociata Scarlatta.","L\u2019esercito principale della Crociata occupa la Mano di Tyr e combatte i non-morti con grande zelo ma scarso successo, mentre l\u2019Alba d\u2019Argento accoglie alla Light's Hope Chapel chiunque voglia dare una mano. Citt\xe0 fantasma come Darrowshire e Corin's Crossing ricordano battaglie perdute, e i troll Amani attaccano da Zul'Mashar, a nord, per riprendersi le loro terre ancestrali."]},"zone:winterspring":{title:"Fontefredda",summary:"Una valle innevata sulle pendici di Hyjal, condivisa da mercanti goblin, fiere del gelo, draghi blu e demoni.",body:["Fontefredda \xe8 una valle di nevi quasi perenni sulle pendici del Monte Hyjal, dove gli Elfi della Notte iniziarono a ricostruire dopo la Grande Frattura. La citt\xe0 goblin di Everlook commercia con chiunque, gli Elfi della Notte occupano ancora il villaggio di Starfall e gli addestratori della Frostsaber Rock allevano i felini bianchi della valle. I draghi blu hanno la loro tana nelle grotte di Mazthoril.","Il sud della valle \xe8 caduto in mano ai demoni nella Darkwhisper Gorge, e i furbolg Winterfall si sono inselvatichiti. In Forever, uno degli ingressi all\u2019incursione delle Barrow Deeps si raggiunge attraverso Fontefredda."]},"zone:deadwind-pass":{title:"Deadwind Pass",summary:"Un passo morto e flagellato dal vento, dominato da Karazhan, la torre dell\u2019ultimo Guardiano, Medivh.",body:["Il Deadwind Pass \xe8 un canyon frastagliato di alberi pietrificati e senza foglie tra Duskwood e la Palude del Dolore, dove un vento lamentoso non smette mai di soffiare. Al centro si erge Karazhan, la torre d\u2019avorio di Medivh, l\u2019ultimo Guardiano di Tirisfal, la cui possessione da parte di Sargeras apr\xec la strada all\u2019Orda. Anche se Medivh \xe8 morto da tempo, la sua torre continua a far trapelare magia oscura nella regione.","Ogre del Deadwind, demoni e spiriti inquieti vagano per il passo, le tombe del Morgan's Plot non trovano pace e i viaggiatori sussurrano che un nuovo potere si sia impadronito della torre. Quasi tutti lo attraversano in fretta."]},"zone:moonglade":{title:"Radura Lunare",summary:"Un pacifico santuario dei druidi nel nord di Kalimdor, sede del Circolo Cenariano.",body:["La Radura Lunare \xe8 una valle nascosta nel nord di Kalimdor, sacra ai druidi da migliaia di anni. Malfurion Grantempesta vi radun\xf2 i druidi per fondare il Circolo Cenariano, e il riflesso della valle nel Sogno di Smeraldo \xe8 il luogo pi\xf9 sacro di quel reame. Nella citt\xe0 di Nighthaven, il custode Remulos, figlio di Cenarius, veglia sull\u2019ordine.","Dalla Terza Guerra il Circolo ha aperto la Radura Lunare a tutti coloro che seguono la via druidica, e tauren ed Elfi della Notte ne condividono oggi le rive in pace. I guardiani della Radura Lunare non tollerano violenze nel santuario, e ogni anno Nighthaven celebra la Festa della Luna."]},"zone:silithus":{title:"Silithus",summary:"Un deserto bruciato dal sole e pieno di alveari di insetti nel sud-ovest di Kalimdor, dove il Circolo Cenariano sorveglia le porte sigillate di Ahn'Qiraj.",body:["Silithus \xe8 un deserto rovente all\u2019estremo sud-ovest di Kalimdor, interrotto soltanto dagli altissimi alveari dei silitidi. Dalla Guerra delle Sabbie Mobili, i Qiraji insettoidi sono rinchiusi dietro il Muro dello Scarabeo eretto dagli stormi di draghi, eppure i loro sciami di silitidi non hanno mai smesso di moltiplicarsi.","Il Circolo Cenariano sorveglia la minaccia dal Presidio Cenariano, mentre i cultisti del Martello del Crepuscolo si radunano in accampamenti tra le dune per scopi tutti loro. Dietro il muro attende il tempio-fortezza di Ahn'Qiraj."]}}},1775,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"instances1",{enumerable:!0,get:function(){return o}});const o={"instance:hall-of-thanes":{title:"Hall of Thanes",summary:"La cripta reale di Forgiardente, violata da intrusi che i nani sospettano siano Ferroscuro.",body:["Sotto Forgiardente si trova la Hall of Thanes, dove i nani seppelliscono i loro sovrani e curano le tombe con grande attenzione. L\u2019ingresso si apre sulla soglia dell\u2019High Seat, nel cuore della citt\xe0: una passeggiata per l\u2019Alleanza, un\u2019incursione audace per qualsiasi gruppo dell\u2019Orda. Ora alcuni intrusi si sono fatti strada con la forza fino alle tombe consacrate. I nani sospettano il clan Ferroscuro, e l\u2019antica pietra \xe8 piena di sussurri spettrali.","La maggior parte delle missioni \xe8 per l\u2019Alleanza e comincia a Kharanos o nei dintorni di Forgiardente, anche se una delle missioni all\u2019interno viene affidata da un fantasma neutrale. Quattro nemici sbarrano la strada: Faldrim Anvilmar, Magmatus, Plunder e Durgen Dirgehammer."],unknowns:["Chi siano davvero gli intrusi; il testo ufficiale dice solo che i nani sospettano il clan Ferroscuro.","Che cosa si sia risvegliato nelle sale e quale storia ci sia dietro ciascuno dei quattro nemici."]},"instance:ragefire-chasm":{title:"Voragine Infuocata",summary:"Caverne vulcaniche sotto Orgrimmar, dove troggs e un culto al servizio dei demoni minacciano la nuova capitale dell\u2019Orda.",body:["Sotto Orgrimmar si snoda un labirinto di caverne illuminate dalla lava, e l\u2019Orda ha scoperto che la sua nuova capitale non dorme sonni tranquilli. Dei troggs noti come gli Infuocati sono risaliti dai tunnel profondi, e quando l\u2019anziana tauren Magatha Grimtotem ha cercato di fare pace con loro, ha trovato solo violenza.","Peggio ancora, una setta chiamata Searing Blade, fedele al demoniaco Concilio dell\u2019Ombra, si \xe8 nascosta nella voragine per tramare contro tutto ci\xf2 che il popolo di Thrall ha costruito. La guida Taragaman the Hungerer, una vilguardia, affiancato dallo stregone Jergosh the Invoker e dal satiro Bazzalan. Per molti giovani eroi dell\u2019Orda, queste caverne sono la prima spedizione."]},"instance:ruins-of-lordaeron":{title:"Ruins of Lordaeron",summary:"La capitale in rovina sopra Sepulcra, dove i Reietti si riprendono il loro passato mentre un negromante accumula potere.",body:["I Reietti stanno cercando di riprendersi la capitale in rovina sopra la loro Sepulcra. Le macerie custodiscono ancora cimeli di famiglia e ricordi preziosi, ma il Flagello infesta le strade distrutte e si dice che un negromante stia accumulando potere entro le mura. Gli avventurieri vengono chiamati ad aiutare a rendere sicura la citt\xe0.","I gruppi dell\u2019Orda raggiungono facilmente l\u2019ingresso da Sepulcra, mentre quelli dell\u2019Alleanza devono avventurarsi nelle terre dell\u2019Orda. Entrambe le fazioni trovano missioni: quelle dell\u2019Orda iniziano a Sepulcra, a Selvargentea e a Tirisfal, quelle dell\u2019Alleanza all\u2019interno delle rovine stesse. Il cammino passa per Witherfang, The Baron, Viktor the Vile, The Abandoned e Bjork fino all\u2019ultimo nemico, Rath'mael."],unknowns:["Chi sia il negromante e a che cosa serva il potere che accumula.","Quanto dell\u2019antica capitale i Reietti intendano ricostruire."]},"instance:deadmines":{title:"Miniere della Morte",summary:"La miniera d\u2019oro abbandonata delle Marche Occidentali, dove la Confraternita Defias di Edwin VanCleef costruisce in segreto una nave da guerra.",body:["Prima della Prima Guerra, queste gallerie erano le miniere d\u2019oro pi\xf9 ricche delle terre umane; il saccheggio di Roccavento da parte degli orchi le lasci\xf2 vuote. Ora la Confraternita Defias ne ha fatto la sua fortezza nascosta. Il suo capo, Edwin VanCleef, era un maestro scalpellino che aiut\xf2 a ricostruire Roccavento dopo la guerra, finch\xe9 i nobili della citt\xe0 non si rifiutarono di pagare la sua gilda. Traditi, i suoi lavoratori divennero fuorilegge e si sparsero per le Marche Occidentali.","La via d\u2019accesso parte dal villaggio in rovina di Moonbrook. Molto pi\xf9 in basso, goblin come Sneed e Gilnid aiutano i Defias a completare una grande nave in un\u2019insenatura nascosta, sorvegliata da Mr. Smite e da Captain Greenskin."]},"instance:wailing-caverns":{title:"Caverne dei Lamenti",summary:"Caverne sotto le Savane, dove il sogno di rinascita del druido Naralex si \xe8 trasformato in incubo.",body:["Le Caverne dei Lamenti devono il loro nome al gemito del vento e del vapore che filtrano dalle crepe nella roccia. Il druido Elfo della Notte Naralex le scopr\xec e sperava di collegare le loro sorgenti sotterranee al Sogno di Smeraldo, perch\xe9 la vita verde tornasse a diffondersi sulle aride Savane. Ma mentre meditava, fu invece l\u2019Incubo di Smeraldo a sopraffarlo.","Intrappolato nel sonno, Naralex riversa ora quella corruzione nelle caverne. Le loro creature si sono deformate in bestie deviate, e quasi tutti i suoi discepoli sono impazziti diventando i Druids of the Fang, tra cui Lady Anacondra e i lord Cobrahn, Pythas e Serpentis. Risvegliare Naralex significa affrontare Mutanus the Devourer."]},"instance:shadowfang-keep":{title:"Forte Zannascura",summary:"Una fortezza infestata di Selvargentea, dove il folle arcimago Arugal ospita i worgen che lui stesso ha scatenato.",body:["Il Kirin Tor stava perdendo la lotta della Terza Guerra contro il Flagello, e ogni mago che cadeva si rialzava presto dalla parte del nemico. L\u2019arcimago Arugal ignor\xf2 gli avvertimenti dei colleghi e cerc\xf2 aiuto oltre il mondo, evocando i feroci worgen. Questi fecero a pezzi i non-morti, poi le stesse file di Dalaran, e invasero la fortezza del barone Silverlaine sulla collina sopra Pyrewood.","Il senso di colpa spezz\xf2 la mente di Arugal. Ora chiama gli uomini lupo suoi figli e si nasconde con loro nella fortezza, ribattezzata Zannascura e sorvegliata dal grande lupo Fenrus. Il fantasma del barone non se n\u2019\xe8 mai andato, e i Reietti di Selvargentea vogliono l\u2019arcimago morto."]},"instance:excavation-site-wetlands":{title:"Excavation Site: Wetlands",summary:"Uno scavo sopra il Whelgar's Excavation Site ha aperto un luogo che il tempo non ha toccato, sorvegliato da costrutti dei Titani rimasti senza padrone.",body:["Qualcosa si \xe8 risvegliato sulle colline delle Wetlands, vicino a Thelgen Rock e a Dun Algaz. La nebbia scende lungo i pendii sopra il Whelgar's Excavation Site e una luce tremola all\u2019orizzonte. Oltre lo scavo, la terra sembra intatta dal passare delle ere; macchine dei Titani rimaste senza padrone e una fauna feroce custodiscono segreti che la Lega degli Esploratori \xe8 ansiosa di svelare.","Le missioni dell\u2019Alleanza iniziano al Porto di Menethil, a Greenwarden's Grove e a Lakeshire, quelle dell\u2019Orda a Orgrimmar e Hammerfall. Saltspine e Shadetooth sbarrano la strada al Relic Guardian, la cui sconfitta lascia una reliquia dei Titani che avvia una missione per entrambe le fazioni."],unknowns:["Che cosa si sia risvegliato oltre lo scavo e che cosa provochi la nebbia e le luci.","Chi abbia costruito il luogo e a che cosa serva la reliquia dei Titani."]},"instance:stormwind-stockade":{title:"Segrete di Roccavento",summary:"La prigione di Roccavento, conquistata dai suoi stessi detenuti in una rivolta guidata dai Defias.",body:["Le Segrete si trovano nel cuore della citt\xe0 di Roccavento e rinchiudono ladri, assassini e prigionieri politici. Non molto tempo fa i detenuti si sono ribellati, hanno rivelato la loro fedelt\xe0 alla Confraternita Defias e hanno cacciato le guardie; ora sono loro a comandare i bracci delle celle.","Il loro capo \xe8 Bazil Thredd, un agente dei Defias. Tra i prigionieri ci sono l\u2019orco Roccianera Targorr the Dread, il nano Ferroscuro Kam Deepfury e il tombarolo Dextren Ward. Molti erano stati condannati a morte, ma la burocrazia dei nobili continuava a rinviare le sentenze, cos\xec Lakeshire, Darkshire e persino Forgiardente mandano dentro di nascosto degli avventurieri per chiudere la questione."]},"instance:city-of-dalaran":{title:"City of Dalaran",summary:"La citt\xe0 del Kirin Tor nelle Montagne di Alterac, dove la barriera che celava il suo restauro \xe8 caduta e la magia \xe8 fuori controllo.",body:["Per un certo tempo una barriera magica ha nascosto i lavori di restauro di Dalaran. Ora quello scudo \xe8 caduto e la citt\xe0 si mostra in pieno caos arcano: gli incantesimi falliscono, i costrutti girano liberi e la magia grezza si riversa nelle strade. Il Kirin Tor ha bisogno di aiuto, ma solo da persone di cui si fida.","Gli eroi dell\u2019Alleanza conquistano quella fiducia iniziando da Emissary Jacques a Southshore; quelli dell\u2019Orda iniziano da Magus Wordeen Voidglare al Mulino di Tarren. Entrambe le strade portano a un\u2019immagine dell\u2019arcimaga Modera sulla riva meridionale del Lago Lordamere, che consegna la Dalaran Sewer Key. Dalle fogne, i gruppi scelgono il proprio percorso attraverso la citt\xe0 verso l\u2019origine dei guai; l\u2019ultimo nemico \xe8 lo Shade of the Archmage."],unknowns:["Che cosa abbia causato lo scompiglio e di chi sia l\u2019ombra che fa da ultimo nemico.","A che punto sia il restauro di Dalaran."]},"instance:blackfathom-deeps":{title:"Abissi Neri",summary:"Un tempio sommerso di Elune sulla costa di Valtetra, oggi un santuario dove dei cultisti accudiscono una bestia degli Dei Antichi.",body:["Un pozzo circondato da scale sullo Zoram Strand di Valtetra scende verso sale allagate che un tempo formavano un tempio di Elune, la dea lunare degli Elfi della Notte. La Grande Frattura spezz\xf2 il santuario e lo trascin\xf2 sotto il mare, dove dorm\xec per ere finch\xe9 naga e satiri, avidi del potere che ancora vi aleggia, non vennero a esplorarlo.","Oggi il culto del Martello del Crepuscolo prega nelle vasche pi\xf9 profonde sotto Twilight Lord Kelris, accudendo Aku'mai, una bestia mostruosa cara agli Dei Antichi. Sciamani dell\u2019Anello della Terra sono venuti a fermarli, sapendo che ogni richiamo agli Dei Antichi mette in pericolo il mondo intero."]},"instance:razorfen-kraul":{title:"Razorfen Kraul",summary:"La tana ancestrale dei verrospini, nata dai rovi spuntati dal sangue di un semidio caduto.",body:["I verrospini venerano Agamaggan, il grande semidio cinghiale ucciso durante la Guerra degli Antichi. Dove cadde il suo sangue, enormi rampicanti spinosi eruppero dalla terra, e il groviglio pi\xf9 grande, all\u2019estremo sud delle Savane, \xe8 il Razorfen, il luogo che i verrospini onorano come la sua tomba.","Razorfen Kraul \xe8 la loro casa ancestrale, un labirinto di tane e cunicoli coperti di rovi governato da Charlga Razorflank, la Megera. Sacerdoti della trib\xf9 Death's Head ne percorrono gi\xe0 i passaggi, e gli esploratori riferiscono di non-morti che si radunano nella regione, segno temuto che il Flagello abbia messo gli occhi su Kalimdor."]},"instance:gnomeregan":{title:"Gnomeregan",summary:"La capitale perduta degli gnomi a Dun Morogh, avvelenata da un\u2019epurazione radioattiva dopo un\u2019invasione di troggs e il consiglio di un traditore.",body:["Costruita nel cuore delle montagne di Dun Morogh, Gnomeregan era la pi\xf9 grande meraviglia ingegneristica degli gnomi. Poi i troggs risalirono dal sottosuolo e la invasero. Il Gran Inventore Mekkatorque segu\xec il consiglio del suo consigliere, Sicco Thermaplugg, e inond\xf2 la citt\xe0 di radiazioni per uccidere gli invasori, ma l\u2019epurazione uccise anche la maggior parte degli gnomi. I sopravvissuti fuggirono a Forgiardente.","Fu un tradimento. Thermaplugg rimase indietro, si incoron\xf2 signore delle rovine e ora comanda gnomi lebbrosi, troggs e macchine impazzite come l\u2019Electrocutioner 6000 e il Crowd Pummeler 9-60. Gli esuli hanno giurato di riprendersi la loro casa."]},"instance:scarlet-monastery-graveyard":{title:"Monastero Scarlatto: Cimitero",summary:"Le cripte del monastero della Crociata Scarlatta, dove opera il suo interrogatore e i morti si rifiutano di riposare.",body:["Il monastero nel nord delle Radure di Tirisfal fu costruito come casa di studio per i sacerdoti di Lordaeron. Dopo che il Flagello ebbe travolto il regno nella Terza Guerra, i fanatici della Crociata Scarlatta se ne impadronirono e ne fecero la loro roccaforte. Sospettano che chiunque non sia umano porti la piaga e accolgono gli stranieri con le lame anzich\xe9 con le domande.","Il Cimitero \xe8 la prima ala che la maggior parte dei gruppi visita. Le sue celle appartengono all\u2019Interrogatore Vishas, Bloodmage Thalnos si aggira tra le tombe, e morti senza pace come Azshir the Sleepless, Ironspine e il Campione Caduto vagano per le cripte."]},"instance:scarlet-monastery-library":{title:"Monastero Scarlatto: Biblioteca",summary:"L\u2019archivio della Crociata Scarlatta, dove un maestro dei segugi e un arcanista sorvegliano i libri dell\u2019ordine.",body:["Un tempo i sacerdoti di Lordaeron venivano a studiare in questo monastero di Tirisfal. La Crociata Scarlatta, che se ne impadron\xec dopo la Terza Guerra, ha conservato i libri ma perso la mitezza: i suoi fanatici credono che chiunque non sia umano possa diffondere la piaga e sorvegliano il loro archivio con la stessa ferocia delle loro mura.","Il Maestro dei Segugi Loksey e i suoi cani danno la caccia agli intrusi nelle sale esterne, e l\u2019Arcanista Doan veglia sugli scaffali interni. Molti vengono per i libri stessi: gli studiosi di Forgiardente vogliono un volume sulla mitologia dei Titani, mentre i Reietti cercano la cronaca dei caduti tenuta dalla Crociata stessa."]},"instance:drowned-city":{title:"Drowned City",summary:"Antiche rovine troll riemerse dal mare al largo di Rovotorto, ora percorse da troll e naga.",body:["Al largo di Rovotorto, a ovest di Grom'gol, una citt\xe0 troll che il mare aveva inghiottito \xe8 riemersa. Strade che nessuno percorreva da ere sono ora a cielo aperto, troll e naga vi si sono gi\xe0 insediati, e una nave pirata nei paraggi sembra aver fatto una pessima fine.","Per entrare, i gruppi si immergono e cercano la via sotto la linea di galleggiamento. Una volta dentro, combattono a cielo aperto mentre il tempo peggiora: la nebbia si fa pioggia e la pioggia una vera tempesta per lo scontro finale."],unknowns:["Perch\xe9 la citt\xe0 sia riemersa proprio ora e quale popolo troll l\u2019abbia costruita.","Chi guidi i troll e i naga all\u2019interno; i dati di questa guida non elencano ancora boss.","Che cosa sia successo alla nave pirata."]},"instance:scarlet-monastery-armory":{title:"Monastero Scarlatto: Armeria",summary:"Il campo d\u2019addestramento e l\u2019arsenale della Crociata Scarlatta, dominato dal suo campione Herod.",body:["Dietro le mura del monastero nelle Radure di Tirisfal, la Crociata Scarlatta addestra i suoi soldati. L\u2019ordine nacque dalla rovina di Lordaeron nella Terza Guerra e crede che chiunque non sia umano possa portare la piaga, perci\xf2 alle sue reclute si insegna a colpire per prime.","L\u2019Armeria ospita i cortili d\u2019addestramento, le caserme e i depositi d\u2019armi, e il suo padrone \xe8 Herod, il Campione Scarlatto, un bruto gigantesco che brandisce un\u2019ascia enorme e turbina in mezzo ai suoi assalitori. Batterlo dimostra che un gruppo \xe8 pronto per la cattedrale nel cuore del monastero."]},"instance:razorfen-downs":{title:"Razorfen Downs",summary:"Gli antichi luoghi di sepoltura dei verrospini, conquistati dal Flagello sotto il lich Amnennar the Coldbringer.",body:["Razorfen Downs cresce dagli stessi rovi giganti del Kraul ed \xe8 il luogo dove i verrospini seppelliscono i loro morti. I loro sommi sacerdoti, i Death's Head, ne custodivano un tempo la sacralit\xe0. Tutto cambi\xf2 quando il Flagello raggiunse Kalimdor: il lich Amnennar the Coldbringer prese al suo servizio i sacerdoti della trib\xf9 e riemp\xec i rovi di morti risorti.","I verrospini liberi lottano ora per riconquistare la loro citt\xe0 dei morti prima che il potere del lich si estenda al resto delle Savane. Un gruppo deve farsi strada oltre Tuten'kash, Mordresh Fire Eye, Glutton e Plaguemaw the Rotting per raggiungere Amnennar in persona."]},"instance:scarlet-monastery-cathedral":{title:"Monastero Scarlatto: Cattedrale",summary:"Il cuore del Monastero Scarlatto, dove il comandante Mograine guida i fedeli e l\u2019Alta Inquisitrice Whitemane rialza i caduti.",body:["La cattedrale \xe8 il cuore del monastero della Crociata Scarlatta nelle Radure di Tirisfal e la sede dei suoi capi in quel luogo. Il Comandante Scarlatto Mograine guida la fanatica guarnigione, ma la vera autorit\xe0 appartiene all\u2019Alta Inquisitrice Whitemane, una sacerdotessa capace di richiamare il suo campione caduto perch\xe9 torni a combattere.","La Crociata \xe8 nata dalla caduta di Lordaeron e vede ancora la piaga in ogni straniero. \xc8 qui che la sua convinzione brucia pi\xf9 forte: il comandante combatte fino all\u2019ultimo e, quando cade, Whitemane scende dal presbiterio per continuare la lotta e rialzarlo ancora."]}}},1776,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"instances2",{enumerable:!0,get:function(){return o}});const o={"instance:kroldok-stronghold":{title:"Krol'dok Stronghold",summary:"Una fortezza degli ogre nelle Riverglades, i cui predoni rapiscono i viaggiatori e da cui al calar della notte si levano canti.",body:["Krol'dok \xe8 la fortezza degli ogre delle Riverglades, e la sua storia risale agli anni successivi alla Seconda Guerra. Quando le forze della vecchia Orda nella regione assediarono Farholde Keep, Fern Crimsonleaf si infiltr\xf2 nel loro accampamento e ne uccise i capi. Senza guida, l\u2019esercito, pi\xf9 numeroso, perse una battaglia costosa contro la Brotherhood of the Horse e fugg\xec di nuovo a Krol'dok.","Ora i suoi esploratori ogre colpiscono in tutte le Riverglades, rapendo viaggiatori e saccheggiando insediamenti. Le loro tracce finiscono in una vasta fortezza di officine, accampamenti e passaggi sorvegliati da vicino. I gruppi vi entrano per fermare le razzie e scoprire il significato degli strani canti che si levano dalla fortezza al calar della notte."],unknowns:["Chi comandi oggi la fortezza; i dati di questa guida non elencano ancora boss.","Che cosa siano i canti e chi li guidi.","Che legame abbiano questi ogre con il Martello del Crepuscolo e con gli ogre Bolder'ok in altre parti delle Riverglades."]},"instance:uldaman":{title:"Uldaman",summary:"Una camera dei Titani nelle Maleterre, dove scavatori nanici risvegliarono i troggs e trovarono indizi sulle proprie origini.",body:["Uldaman \xe8 una camera che i custodi dei Titani sigillarono nel profondo delle montagne di Khaz Modan, in quelle che oggi sono le Maleterre. Doveva contenere i troggs, una creazione primitiva che i Titani giudicarono un fallimento. Prima della Terza Guerra, scavatori di Forgiardente vi fecero irruzione, e i troggs che risvegliarono massacrarono gran parte della spedizione.","Ora la Lega degli Esploratori, predoni Ferroscuro e trib\xf9 di troggs si contendono le sue sale. Nel profondo si trovano i Dischi di Norgannon, documenti dei Titani che rivelano che i nani discendono dai terrigeni dalla pelle di pietra; li custodisce Archaedas, forgiato dai Titani, che si leva ancora contro chiunque disturbi la sua camera."]},"instance:zulfarrak":{title:"Zul'Farrak",summary:"La citt\xe0 riarsa dal sole dei troll Sandfury a Tanaris, dove un dio idra dorme in una vasca sacra.",body:["Tanaris era un tempo una giungla che faceva parte delle terre dei troll Gurubashi, e Zul'Farrak era una delle loro citt\xe0. Quando la Grande Frattura trasform\xf2 la regione in deserto, i troll Farraki rimasti si adattarono e divennero troll delle sabbie. Oggi la citt\xe0 appartiene alla trib\xf9 Sandfury, temuta per la sua crudelt\xe0 e la sua magia oscura.","Gli avventurieri vi giungono per molte ragioni. Le voci collocano entro le sue mura entrambe le met\xe0 della spada troll spezzata Sul'thraze the Lasher, una banda di mercenari in fuga da Gadgetzan vi \xe8 finita per errore ed \xe8 stata catturata, e in una vasca sacra nel cuore della citt\xe0 dorme Gahz'rilla, un\u2019idra che i Sandfury venerano come un semidio e risvegliano solo quando hanno sacrifici da offrire."]},"instance:alcaz-prison":{title:"Alcaz Prison",summary:"Una prigione a lungo avvolta nelle voci sull\u2019isola di Alcaz, in Acquemorte, finalmente aperta, dove Defias e naga sono in guerra.",body:["Acquemorte mormora da tempo dell\u2019isola di Alcaz e dei prigionieri di alto rango che vi sarebbero rinchiusi; alcune voci fanno persino il nome di re Varian Wrynn di Roccavento. Nessuno riusciva a raggiungere la prigione per scoprire la verit\xe0. Ora i suoi cancelli sono aperti.","All\u2019interno, la Confraternita Defias e i naga si combattono. I gruppi approfittano del caos per perquisire le celle, affrontare chi le controlla e raccogliere nuovi indizi su un mistero che i regni conoscono gi\xe0 bene."],unknowns:["Se re Varian Wrynn sia o sia stato prigioniero qui; il testo ufficiale riporta solo voci.","Chi gestisca la prigione e perch\xe9 Defias e naga si combattano.","Quali boss attendano all\u2019interno; i dati di questa guida non ne elencano ancora."]},"instance:maraudon":{title:"Maraudon",summary:"Le caverne sacre dei centauri a Desolanda, avvelenate dal dolore della principessa della terra Theradras.",body:["La leggenda racconta una storia cupa sulla nascita dei centauri. Il loro padre era Zaetar, figlio del semidio Cenarius; la madre era la principessa Theradras, figlia del signore elementale della terra. I primi centauri si rivoltarono contro Zaetar e lo uccisero, e si dice che Theradras, in lutto, abbia legato il suo spirito dentro Maraudon, un gesto la cui corruzione avvelena ancora le caverne.","I clan dei centauri considerano Maraudon un sacro luogo di sepoltura, ma fantasmi di centauri senza pace, elementali distorti e velenose creature vegetali riempiono ora la Wicked Grotto, la Foulspore Cavern e le Earth Song Falls. Celebras, nipote di Zaetar, venne a liberare lo spirito dello zio e cadde a sua volta preda della corruzione. Sul fondo attende Theradras."]},"instance:temple-of-atalhakkar":{title:"Tempio di Atal'Hakkar",summary:"Il Tempio Sommerso della Palude del Dolore, dove i sacerdoti Atal'ai cercano ancora di evocare il loro dio del sangue, Hakkar.",body:["Gli Atal'ai erano sacerdoti troll che volevano portare nel mondo Hakkar the Soulflayer, il dio del sangue, e la lotta per fermarli lacer\xf2 l\u2019Impero Gurubashi pi\xf9 di mille anni fa. Sconfitti e cacciati, costruirono un tempio nella Palude del Dolore per preparare il suo ritorno, finch\xe9 l\u2019Aspetto Ysera non scopr\xec il piano e lo fece sprofondare nel fango.","Da allora i draghi verdi sorvegliano le rovine sommerse, ma gli Atal'ai hanno resistito e pregano ancora Hakkar sotto la guida di Jammal'an the Prophet. Pi\xf9 in basso indugia l\u2019Ombra di Eranikus, consorte di Ysera, con la mente oscurata dall\u2019Incubo di Smeraldo."]},"instance:blackrock-depths":{title:"Sprofondi di Roccianera",summary:"Shadowforge City, la capitale dei nani Ferroscuro nel cuore del Massiccio Roccianera, governata dall\u2019imperatore Dagran Thaurissan all\u2019ombra di Ragnaros.",body:["Pi\xf9 di due secoli fa, il signore stregone Ferroscuro Thaurissan tent\xf2 di vincere una guerra perduta con un\u2019evocazione disperata e richiam\xf2 invece Ragnaros, il Signore del Fuoco. L\u2019esplosione sollev\xf2 il Massiccio Roccianera e leg\xf2 il suo clan alla volont\xe0 del Signore del Fuoco. I loro discendenti faticano ancora per Ragnaros nei tunnel ardenti sotto la montagna.","Gli Sprofondi di Roccianera sono il loro regno: una prigione, l\u2019arena chiamata Ring of Law, la taverna Grim Guzzler, la Forgia Nera e la stessa Shadowforge City. L\xec l\u2019imperatore Dagran Thaurissan siede sul trono accanto alla principessa Moira Barbabronzea, il cui padre, re Magni di Forgiardente, crede che sia trattenuta l\xec da un incantesimo."]},"instance:warpwood-quarter":{title:"Warpwood Quarter",summary:"Il distretto orientale della rovinata Eldre'Thalas, invaso da piante corrotte sotto il satiro Alzzin the Wildshaper.",body:["Maglio Infausto, a Feralas, era un tempo Eldre'Thalas, una citt\xe0 dove gli arcanisti pi\xf9 riservati della regina Azshara custodivano il suo prezioso sapere. La Grande Frattura la lasci\xf2 in rovina, e nel corso delle ere ogre, satiri e creature ancora pi\xf9 strane si insediarono nei suoi distretti.","Il Warpwood Quarter, a est, \xe8 caduto in mano ad Alzzin the Wildshaper, un satiro che ha corrotto il Frutto della Fertilit\xe0, che ora produce solo viticci vili. Antichi distorti, frustatori, demoni e satiri gli obbediscono, e l\u2019intero distretto si \xe8 inselvatichito. Persino il dispettoso imp Pusillin trascina gli intrusi in un allegro inseguimento per le sue sale."]},"instance:blackmaw-hold":{title:"Blackmaw Hold",summary:"Una grande citt\xe0 furbolg dietro un cancello a lungo sigillato ad Azshara, dove il clan Blackmaw combatte una corruzione che si diffonde.",body:["Dietro un cancello di Azshara rimasto chiuso per moltissimo tempo si trova una grande citt\xe0 dei furbolg. Il clan Blackmaw che vi abita combatte una corruzione che filtra attraverso i suoi boschetti e lungo i tortuosi tunnel sotto le montagne.","La roccaforte \xe8 una lunga avventura per i gruppi al livello massimo, con diversi percorsi e molti boss. Si dice che le sue profondit\xe0 nascondano una via che porta ancora pi\xf9 in basso sotto Azeroth, e la panoramica delle incursioni di Blizzard indica Blackmaw Hold come uno degli ingressi ai Barrow Deeps."],unknowns:["Che cosa sia la corruzione e da dove venga.","Chi abbia sigillato il cancello e perch\xe9.","Quali boss attendano all\u2019interno; i dati di questa guida non ne elencano ancora."]},"instance:lower-blackrock-spire":{title:"Bastione Roccianera Inferiore",summary:"Le sale inferiori del bastione in cima al Massiccio Roccianera, caserma dell\u2019Orda Oscura di Rend Manonera.",body:["Per secoli il bastione che corona il Massiccio Roccianera fu una roccaforte dei Ferroscuro. Tutto fin\xec quando Nefarian, figlio di Alamorte, ne conquist\xf2 i livelli superiori con la sua progenie draconica e si rivolt\xf2 contro i nani. Trov\xf2 un alleato in Rend Manonera, un orco che si proclama Capoguerra di un\u2019Orda Oscura che rifiuta di seguire Thrall.","Il Bastione Roccianera Inferiore \xe8 la caserma di quell\u2019Orda Oscura. Legioni di orchi Roccianera, ogre Spirestone agli ordini di Highlord Omokk, troll Smolderthorn del Cacciatore d\u2019Ombre Vosh'gajin e i ragni attorno a Mother Smolderweb si dividono le sue sale in rovina sotto Overlord Wyrmthalak. L\u2019\xe9lite e i draghi attendono ancora pi\xf9 in alto, nel Bastione Roccianera Superiore."]},"instance:capital-gardens":{title:"Capital Gardens",summary:"Il distretto occidentale di Eldre'Thalas, dove gli ultimi Highborne degli Shen'dralar si nutrono di un demone in gabbia.",body:["Eldre'Thalas, oggi chiamata Maglio Infausto, fu costruita per custodire i segreti arcani della regina Azshara, e i suoi custodi, gli Shen'dralar, sopravvissero alla Grande Frattura. Privati del potere del Pozzo dell\u2019Eternit\xe0, il loro capo, il principe Tortheldrin, fece innalzare cinque piloni per imprigionare il demone Immol'thar, e il suo popolo ne attinse l\u2019energia per restare immortale.","Nel corso dei secoli la prigione si indebol\xec. Per conservare il proprio potere, Tortheldrin si rivolt\xf2 contro gli altri Shen'dralar e li prosciug\xf2. I Capital Gardens, un tempo parco e corte degli Highborne, ospitano ora i suoi ultimi seguaci fedeli, alberi avvizziti, antichi infuriati e il demone in gabbia in persona."]},"instance:scholomance":{title:"Scholomance",summary:"La scuola di negromanzia di Kel'Thuzad nelle cripte sotto Caer Darrow, consegnata al Flagello dalla famiglia Barov.",body:["Su un\u2019isola del Lago Darrowmere, nelle Terre Infette Occidentali, sorge Caer Darrow, un tempo la fortezza della nobile famiglia Barov. Quando lo stregone Kel'Thuzad radun\xf2 seguaci per il suo Culto dei Dannati, promise l\u2019immortalit\xe0 in nome del Re dei Lich, e i Barov gli cedettero la fortezza e le sue cripte. Il culto trasform\xf2 le cripte nella Scholomance, una scuola dove i negromanti si addestravano a diffondere la piaga.","I Barov hanno visto esaudito il loro desiderio nel modo peggiore e ora infestano le sale come non-morti. Il lich Ras Frostwhisper governa la scuola per conto del Flagello, Darkmaster Gandling ne \xe8 il preside e il Ravenian si annida pi\xf9 in basso, pronto a divorare gli studenti deboli."]},"instance:shapers-terrace":{title:"Shaper's Terrace",summary:"Un\u2019antica struttura dei Titani sulle colline settentrionali del Cratere di Un'Goro, alimentata da cristalli del potere raccolti in tutto il cratere.",body:["Sulle alture settentrionali del Cratere di Un'Goro, un\u2019antica struttura dei Titani domina una terra che il tempo sembra aver lasciato in pace. Dinosauri, pozze di catrame, strutture dei Titani e cristalli luminosi fanno tutti parte di questa spedizione, pensata per i gruppi vicini al livello massimo.","Il suo enigma va oltre le mura: i gruppi raccolgono cristalli del potere nel cratere e li usano su console all\u2019interno della terrazza, cos\xec ci\xf2 che trovano nelle terre selvagge plasma le sfide che li attendono dentro."],unknowns:["Chi abbia costruito la terrazza e a che cosa servisse.","Che cosa facciano le console e quali boss attendano all\u2019interno; i dati di questa guida non ne elencano ancora."]},"instance:stratholme":{title:"Stratholme",summary:"La rovina in fiamme della grande citt\xe0 del nord di Lordaeron, divisa tra il Flagello del barone Rivendare e la Crociata Scarlatta.",body:["Stratholme era la citt\xe0 pi\xf9 fiera del nord di Lordaeron e la culla dell\u2019Ordine della Mano d\u2019Argento. Nella Terza Guerra il principe Arthas ne pass\xf2 a fil di spada gli abitanti piuttosto che lasciare che, toccati dalla piaga, risorgessero come non-morti, rompendo cos\xec con il suo mentore Uther. Poco dopo vi si insedi\xf2 il Flagello, e da allora la citt\xe0 brucia.","Oggi due nemici se la spartiscono. La Crociata Scarlatta tiene un lato sotto il Gran Crociato Dathrohan, senza sospettare che si tratti in realt\xe0 del Signore del Terrore Balnazzar sotto mentite spoglie. L\u2019altro lato appartiene al Flagello e al cavaliere della morte barone Rivendare, ricco possidente di Stratholme e amico di Kel'Thuzad prima di unirsi al Culto dei Dannati."]},"instance:gordok-commons":{title:"Gordok Commons",summary:"Il distretto settentrionale di Maglio Infausto, sede di re Gordok e dei suoi ogre, dove chi uccide il re ne prende la corona.",body:["Gli ogre del clan Gordunni si sono impadroniti del quartiere settentrionale dell\u2019antica Eldre'Thalas, la citt\xe0 in rovina degli Highborne oggi chiamata Maglio Infausto. I loro guerrieri pi\xf9 forti, i Gordok, governano dai Commons, e il loro re assume il nome di re Gordok.","Qui l\u2019usanza degli ogre \xe8 semplice: chi uccide il re diventa il nuovo re Gordok. I gruppi pi\xf9 astuti sgusciano oltre le guardie Mol'dar, Fengus e Slip'kik, Stomper Kreeg e il capitano Kromcrush per colpire solo il re, e gli ogre sopravvissuti trattano i vincitori come i loro nuovi sovrani e pagano loro un tributo. Cho'Rush the Observer sta al fianco del re."]},"instance:barrow-deeps":{title:"Barrow Deeps",summary:"Un\u2019incursione per dieci giocatori nella prigione sotto Kalimdor che trattenne Illidan Grantempesta per diecimila anni.",body:["Nel profondo sotto Kalimdor, i Barrow Deeps tennero prigioniero Illidan Grantempesta per diecimila anni. Ora la via verso i loro tunnel \xe8 aperta, e le incursioni scendono per scoprire che cosa sia accaduto a chi \xe8 rimasto nell\u2019oscurit\xe0 e che cosa intendano fare le custodi contro la minaccia che si agita l\xe0 sotto.","Tre vie conducono all\u2019interno, collegate al Monte Hyjal, a Fontefredda e a Blackmaw Hold. Dieci giocatori affrontano otto boss durante la discesa, dalla Deepscar Matriarch e Khalith the Dreadspinner fino a Del'lynar Songwood e, per ultima, Sonya Darkhallow."],unknowns:["Chi abbia aperto i passaggi e quale sia il pericolo l\xe0 sotto.","Chi siano le custodi e quali siano le storie degli otto boss."]},"instance:hyjal-summit":{title:"Hyjal Summit",summary:"Un\u2019incursione per venti giocatori sulla cima del Monte Hyjal, vicino all\u2019Albero del Mondo Nordrassil, con tredici boss e molti percorsi.",body:["Hyjal Summit si trova in cima al Monte Hyjal, vicino all\u2019Albero del Mondo Nordrassil. Un antico guardiano sbarra la strada all\u2019inizio; poi le incursioni scelgono i propri percorsi attraverso la montagna, tra rovine in superficie e sottoterra, combattendo tutto ci\xf2 che minaccia Hyjal finch\xe9 non si apre la via verso gli scontri finali.","Venti giocatori affrontano tredici boss, tra cui Bandalar, il Time-Lost Battalion, il Council of Thorns, il Wild King e l\u2019Ancient of Decay. L\u2019ultimo di tutti \xe8 Nythus the Dreambound."],unknowns:["Quale forza minacci Hyjal; la panoramica ufficiale non la nomina.","Chi sia l\u2019antico guardiano e chi sia Nythus the Dreambound."]},"instance:onyxias-lair":{title:"Antro di Onyxia",summary:"L\u2019antro di Onyxia, madre della covata dello stormo nero, in Acquemorte; possono entrare solo i portatori del Drakefire Amulet.",body:["Nel Wyrmbog di Acquemorte, Onyxia, figlia di Alamorte e sorella di Nefarian, custodisce la sua covata in una caverna di fuoco. La sua arma pi\xf9 potente \xe8 l\u2019inganno. In forma umana, come Lady Katrana Prestor, sussurra alla corte di Roccavento e lavora per mettere i regni mortali gli uni contro gli altri.","Quaranta giocatori la affrontano in uno scontro di fiamme in tre fasi, perci\xf2 le incursioni raccolgono prima resistenza al fuoco. Ogni membro deve anche portare il Drakefire Amulet, ottenuto con una lunga catena di missioni: per l\u2019Alleanza la fuga del maresciallo Windsor dagli Sprofondi di Roccianera e lo smascheramento a Roccavento, per l\u2019Orda Rexxar e il draco Emberstrife. Entrambe terminano con il generale Drakkisath nel Bastione Roccianera Superiore."]}}},1777,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"items",{enumerable:!0,get:function(){return o}});const o={"item:demon-soul":{title:"L\u2019Anima dei Draghi (Anima del Demone)",summary:"Un disco d\u2019oro forgiato da Neltharion per dominare tutti i draghi; diede origine ad Alamorte e, ere dopo, incaten\xf2 lo stormo rosso all\u2019Orda.",body:["Prima della Guerra degli Antichi, il Custode della Terra Neltharion fece fabbricare ai suoi servitori goblin un disco d\u2019oro dall\u2019aspetto modesto, segretamente intriso della corruzione degli Dei Antichi. Convinse gli altri Aspetti a riversarvi parte del loro potere per combattere la Legione Infuocata, poi lo rivolse contro demoni e alleati allo stesso modo. Le energie dell\u2019Anima dei Draghi gli lacerarono il corpo, e Neltharion divenne Alamorte.","Dopo la Grande Frattura, gli Aspetti nascosero il disco nel profondo di quelle che oggi sono le Montagne Crestarossa. Seguendo le visioni di Alamorte, il clan Fauci di Drago lo recuper\xf2, lo ribattezz\xf2 Anima del Demone e lo us\xf2 per schiavizzare Alexstrasza a Grim Batol. L\xec fu infine distrutto, e i draghi rossi tornarono liberi."]},"item:atiesh":{title:"Atiesh, Greatstaff of the Guardian",summary:"Il bastone dei Guardiani di Tirisfal, portato per ultimo da Medivh, poi spezzato e ricercato da Kel'Thuzad.",body:["Atiesh pass\xf2 di Guardiano in Guardiano per generazioni, fino a Medivh, l\u2019ultimo di loro. Le leggende dicono che sia nato da un \xabseme d\u2019odio\xbb e che conferisca a chi lo impugna un potere senza fine; i corvi gli si radunano attorno, e pu\xf2 aprire una via verso Karazhan. Dopo la caduta di Medivh, il Kirin Tor rinchiuse il bastone a Dalaran, dove ogni mago che lo tocc\xf2 fece una brutta fine.","Quando Archimonde distrusse Dalaran, Atiesh si spezz\xf2 in decine di frammenti che si sparsero per Azeroth, e Kel'Thuzad si mise a raccoglierli. Nel gioco originale, le incursioni strappavano i suoi frammenti alla sua necropoli di Naxxramas, facevano restaurare la struttura con l\u2019aiuto del drago bronzeo Anachronos e poi dovevano purificare il bastone a Stratholme sconfiggendo il demone imprigionato al suo interno."]},"item:scepter-of-the-shifting-sands":{title:"Lo Scettro delle Sabbie Mobili",summary:"La chiave del Muro dello Scarabeo che sigillava Ahn'Qiraj, spezzata da un Fandral Staghelm accecato dal dolore.",body:["Quasi mille anni prima della Prima Guerra, gli insettoidi qiraji dilagarono fuori da Ahn'Qiraj, spinti dal Dio Antico C'Thun. L\u2019arcidruido Fandral Staghelm guid\xf2 gli Elfi della Notte contro di loro, ma suo figlio Valstann fu abbattuto sotto i suoi occhi, e le sorti della guerra si capovolsero. Solo con l\u2019aiuto di quattro stormi di draghi gli sciami furono respinti e sigillati dietro il Muro dello Scarabeo.","Il muro si poteva aprire solo colpendo il Gong dello Scarabeo con questo scettro. Fandral, nella furia del suo dolore, lo spezz\xf2, e i suoi pezzi andarono dispersi. Nel gioco originale, gli avventurieri ricomposero lo scettro, suonarono il gong e aprirono di nuovo Ahn'Qiraj."]},"item:doomhammer":{title:"Martelfato",summary:"Il martello da guerra ereditario della stirpe Martelfato, portato da Orgrim in due guerre e consegnato a Thrall.",body:["Forgiato tanto tempo fa su Draenor, il grande martello di pietra nera passava di padre in figlio all\u2019interno di un\u2019unica famiglia orchesca, e su di esso pendeva un\u2019antica profezia dei Roccianera: l\u2019ultimo della stirpe avrebbe portato agli orchi prima la salvezza e poi la rovina, prima che uno straniero sollevasse il martello per la giustizia. Orgrim Martelfato lo impugn\xf2 nella Prima e nella Seconda Guerra e con esso abbatt\xe9 Anduin Lothar, spezzando la lama runica del cavaliere.","Dopo la sconfitta dell\u2019Orda, Orgrim fugg\xec dalla prigionia e combatt\xe9 per liberare il suo popolo dai campi di internamento. Ferito a morte in una di quelle battaglie, diede il martello a Thrall, che non era n\xe9 del suo clan n\xe9 del suo sangue. Thrall lo port\xf2 come simbolo di un\u2019Orda rinata, e la profezia trov\xf2 il suo straniero."]},"item:book-of-medivh":{title:"Il Libro di Medivh",summary:"L\u2019ultimo libro di incantesimi di Medivh giunto fino a noi, usato due volte per squarciare il passaggio tra i mondi.",body:["Dopo la morte di Medivh, il suo libro di incantesimi fu custodito nella biblioteca reale di Roccavento ricostruita, finch\xe9 degli agenti di Alterac non lo rubarono. Grazie a un accordo tra il re di Alterac e il cavaliere della morte dell\u2019Orda Teron Gorefiend, pass\xf2 agli orchi, e su Draenor Ner'zhul lo us\xf2 con altre reliquie per aprire nuovi portali, squarci che fecero a pezzi il suo mondo. Prima che il Portale Oscuro cadesse, Khadgar recuper\xf2 il libro e lo rimand\xf2 a casa in groppa a un grifone.","Il Kirin Tor lo sigill\xf2 in una camera blindata a Dalaran. Durante la Terza Guerra, Kel'Thuzad distrusse quella camera e, con il potere del libro, apr\xec lo squarcio attraverso cui Archimonde e la Legione Infuocata entrarono in Azeroth. In seguito il libro rimase nelle mani del lich."]},"item:frostmourne":{title:"Gelidanima",summary:"La lama runica del Re dei Lich, che reclam\xf2 l\u2019anima di Arthas Menethil tra i ghiacci di Nordania.",body:["Gelidanima era legata alla prigione del Re dei Lich a Corona di Ghiaccio, e Ner'zhul la spinse fuori dal Trono di Ghiaccio per attirare un campione. Attendeva, sorvegliata, in una caverna gelata di Nordania, con l\u2019avvertimento che il suo potere avrebbe segnato l\u2019anima di chiunque l\u2019avesse impugnata. Il principe Arthas, disperato di fermare la piaga, ignor\xf2 l\u2019avvertimento e afferr\xf2 la lama mentre Muradin Barbabronzea giaceva a terra colpito da una scheggia di ghiaccio.","La spada divora le anime di coloro che uccide. Con essa Arthas uccise il Signore del Terrore Mal'Ganis, poi suo padre, re Terenas, e il suo vecchio mentore Uther. Nell\u2019anno 25 riposa accanto al Re dei Lich in persona. In storie successive, oltre Classic, Tirion Fordring la spezz\xf2 con l\u2019Ashbringer."]},"item:ashbringer":{title:"Ashbringer",summary:"Una lama sacra forgiata a Forgiardente per ridurre in cenere i non-morti, poi tradita e corrotta nelle Terre Infette.",body:["Durante la Seconda Guerra, l\u2019Alto Signore Alexandros Mograine della Mano d\u2019Argento trov\xf2 un cristallo oscuro su uno stregone orco ucciso. Quando il Flagello minacci\xf2 Lordaeron, i capi dell\u2019ordine cercarono di distruggerlo con la magia sacra; il cristallo invece assorb\xec la Luce e divenne radioso. Re Magni Barbabronzea lo forgi\xf2 in una spada sulla Grande Incudine di Forgiardente, e nelle mani di Mograine l\u2019Ashbringer riduceva in cenere i non-morti.","Il Signore del Terrore Balnazzar e Kel'Thuzad tramarono la sua caduta. Renault, figlio di Mograine, lo condusse in un\u2019imboscata del Flagello a Stratholme e lo uccise con la sua stessa spada, corrompendola. Nell\u2019anno 25 Alexandros serve Kel'Thuzad come cavaliere della morte, mentre Renault comanda il Monastero Scarlatto. Solo in storie successive la lama fu purificata."]},"item:skull-of-guldan":{title:"Il Teschio di Gul'dan",summary:"Il teschio dello stregone, una reliquia demoniaca che apr\xec portali, avvelen\xf2 Valtetra e trasform\xf2 Illidan.",body:["Gul'dan fu fatto a pezzi dai demoni nella Tomba di Sargeras, ma il suo teschio conserv\xf2 una scheggia della sua malvagit\xe0. Pass\xf2 per diverse mani orchesche finch\xe9 Grom Malogrido non lo port\xf2 a Ner'zhul, che lo us\xf2 per aiutare a riaprire il Portale Oscuro. In seguito Khadgar lo mand\xf2 a Dalaran insieme al Libro di Medivh, e il Kirin Tor custod\xec entrambi.","Quando Dalaran cadde nella Terza Guerra, il Signore del Terrore Tichondrius rub\xf2 il teschio, e il suo potere corruppe le foreste di Valtetra e del Vilbosco. Illidan Grantempesta ne consum\xf2 la magia, divenne per met\xe0 demone e uccise Tichondrius con quel potere. Il guscio vuoto del teschio rimase a Illidan."]},"item:gorehowl":{title:"Gorehowl",summary:"L\u2019ascia ululante della famiglia Malogrido, che abbatt\xe9 sia Cenarius sia Mannoroth.",body:["Gorehowl fu forgiata generazioni prima che Grom Malogrido la ereditasse, e una leggenda dei Cantaguerra racconta che l\u2019ascia fu temprata con i cuori di possenti gronn. Grom, capo del clan Cantaguerra, fu il primo a bere il sangue del signore degli abissi Mannoroth, legando gli orchi alla Legione Infuocata. A Valtetra bevve di nuovo e, con Gorehowl, uccise il semidio Cenarius.","Thrall lo liber\xf2 dalla morsa del demone, e insieme affrontarono Mannoroth. Grom spacc\xf2 l\u2019arma del signore degli abissi e lo uccise con un solo colpo, spezzando la maledizione che gravava sul suo popolo a costo della propria vita. In seguito Thrall conserv\xf2 l\u2019ascia a Orgrimmar."]},"item:horn-of-cenarius":{title:"Il Corno di Cenarius",summary:"Il corno del semidio, che risvegli\xf2 i druidi dal loro lungo sonno e chiam\xf2 gli antenati degli Elfi della Notte sull\u2019Hyjal.",body:["Dopo la caduta di Cenarius, il suo corno rimase alla Radura Lunare sotto la sorveglianza di antichi guardiani. Quando la Legione Infuocata torn\xf2 nella Terza Guerra, la sacerdotessa Tyrande Soffiabrezza lo recuper\xf2 e lo us\xf2 per risvegliare Malfurion Grantempesta dal suo lungo sognare. Malfurion a sua volta lo suon\xf2 per destare i druidi addormentati dell\u2019Artiglio e della Grinfia.","Al culmine della Battaglia del Monte Hyjal, Malfurion suon\xf2 il corno ancora una volta. Migliaia di spiriti ancestrali risposero e si avventarono su Archimonde, distruggendo il signore dei demoni ai piedi dell\u2019Albero del Mondo, anche se il potere scatenato lasci\xf2 ferito Nordrassil."]},"item:sulfuras":{title:"Sulfuras, Mano di Ragnaros",summary:"Il martello ardente del Signore del Fuoco, e la copia pi\xf9 piccola che i maestri fabbri impararono a forgiare a sua immagine.",body:["Sulfuras \xe8 il colossale martello di Ragnaros, una massa di elementium rosso fiammeggiante che il Signore del Fuoco non lascia mai. Nelle guerre elementali di un passato remoto, abbatt\xe9 con esso Thunderaan, il Principe dell\u2019Aria. Dall\u2019evocazione di Thaurissan, Ragnaros governa con il martello in pugno il Nucleo Ardente, sotto il Massiccio Roccianera.","L\u2019arma vera \xe8 troppo grande per mani mortali, ma se ne pu\xf2 realizzare una copia. Nel gioco originale, un maestro fabbro otteneva i progetti di un Martello di Sulfuron da Lokhtos Darkbargainer della Confraternita del Torio, negli Sprofondi di Roccianera, e poi lo univa al raro Occhio di Sulfuras sottratto allo stesso Ragnaros, creando una Mano di Ragnaros a misura di mortale."]},"item:thunderfury":{title:"Thunderfury, Blessed Blade of the Windseeker",summary:"Una spada forgiata attorno all\u2019ultima essenza di Thunderaan, il Principe dell\u2019Aria, che Ragnaros aveva imprigionato.",body:["In un\u2019antica guerra tra fuoco e aria, Ragnaros e i suoi luogotenenti Garr e il barone Geddon sconfissero Thunderaan, il Principe dell\u2019Aria. Il Signore del Fuoco si nutr\xec della sua essenza ma non riusc\xec a divorarla tutta; sigill\xf2 quindi il resto in un talismano, lo spezz\xf2 in due e diede una met\xe0 a ciascun luogotenente: le Bindings of the Windseeker.","Nel gioco originale, le incursioni sottraevano entrambe le met\xe0 a Garr e Geddon nel Nucleo Ardente e le portavano all\u2019Alto Signore Demitrian a Silithus. Con l\u2019essenza stessa del Signore del Fuoco e lingotti di elementium incantato, i legacci evocavano il Principe indebolito; una volta sconfitto, Demitrian forgiava il potere rimastogli nella Thunderfury, una lama che crepita di tempesta viva."]},"item:seal-of-ascension":{title:"Sigillo dell\u2019Ascensione",summary:"Un anello forgiato nel fuoco di drago nero che apriva la cittadella superiore del Bastione Roccianera.",body:["Le sale superiori del Bastione Roccianera, dove Rend Manonera e lo stormo nero tenevano corte, erano sigillate contro gli intrusi. Nel bastione inferiore, uno straniero travestito di nome Vaelan, in realt\xe0 il drago rosso Vaelastrasz, che aveva giurato di dare la caccia a Nefarian, insegnava agli avventurieri a fabbricare una chiave: un sigillo disadorno incastonato con tre gemme sottratte ai comandanti Smolderthorn, Spirestone e Bloodaxe del Bastione.","Poi il sigillo doveva essere forgiato nel fuoco di drago nero. Gli eroi si recavano al Wyrmbog di Acquemorte e costringevano il draco Emberstrife a soffiarci sopra. L\u2019anello finito apriva la cittadella superiore e, nello scontro con Rend, poteva richiamare una proiezione di Vaelastrasz al fianco degli eroi."]},"item:drakefire-amulet":{title:"Drakefire Amulet",summary:"Il talismano spezzato di Onyxia, rifatto con il sangue di un drago nero per diventare la chiave del suo stesso antro.",body:["Travestita da Lady Katrana Prestor, Onyxia si fece strada alla corte di Roccavento con un ciondolo chiamato Occhio del Drago. Non comandava direttamente le menti, ma risvegliava desideri nascosti e allontanava da lei i sospetti. Quando il maresciallo Windsor smascher\xf2 la messinscena, il ciondolo and\xf2 in frantumi, e il drago blu Haleh ne rifece i pezzi, con il sangue del generale Drakkisath, trasformandoli nel Drakefire Amulet.","Gli eroi dell\u2019Orda arrivano allo stesso amuleto per un\u2019altra strada, attraverso Rexxar e le prove dell\u2019antico draco Emberstrife. Ogni membro dell\u2019incursione che entra nell\u2019Antro di Onyxia deve portarlo, e Forever mantiene questa sintonizzazione come una catena di missioni separata per ogni fazione."]},"item:head-of-onyxia":{title:"Testa di Onyxia",summary:"La prova della morte della Madre della Covata, issata sulle porte di Roccavento o di Orgrimmar come stendardo di raccolta.",body:["Onyxia, figlia di Alamorte e sorella minore di Nefarian, custodisce la sua covata in una caverna di Acquemorte mentre trama per piegare al suo volere i regni mortali di Azeroth. Sconfiggerla pose fine a uno dei pi\xf9 lunghi inganni dello stormo nero.","Nel gioco originale, la sua testa veniva riportata a casa come trofeo: i campioni dell\u2019Alleanza la presentavano a Roccavento, quelli dell\u2019Orda a Thrall a Orgrimmar. Issata sopra le porte della citt\xe0, conferiva il Rallying Cry of the Dragonslayer a tutti quelli che si trovavano in citt\xe0, e l\u2019intera capitale festeggiava la vittoria."]},"item:quel-serrar":{title:"Quel'Serrar",summary:"Un\u2019antica lama degli Elfi della Notte custodita dagli Shen'dralar e completata solo nel soffio di un drago.",body:["Quel'Serrar \xe8 una delle lame prismatiche che i fabbri Elfi della Notte forgiarono tanto tempo fa con l\u2019aiuto degli stormi di draghi; la sua gemella, Quel'Delar, fu donata agli Elfi Alti. Per migliaia di anni gli Shen'dralar di Eldre'Thalas la custodirono, in attesa di qualcuno abbastanza forte da risvegliarla.","Nel gioco originale, un guerriero o un paladino che trovava un vecchio compendio sulla caccia ai draghi lo portava al Custode del Sapere Lydros, nella biblioteca di Maglio Infausto, e riceveva una lama non temprata. Riscaldato dal soffio profondo di Onyxia e affondato nel drago ucciso, l\u2019acciaio diventava Quel'Serrar una volta riportato a Lydros."]},"item:rhokdelar":{title:"Rhok'delar e Lok'delar",summary:"Un arco lungo e un bastone vivi, plasmati dagli Antichi corrotti del Vilbosco per il cacciatore che li vendic\xf2.",body:["Quando la Legione Infuocata dilag\xf2 su Kalimdor, avvelen\xf2 la valle che divenne il Vilbosco. I suoi Antichi pi\xf9 potenti avvizzirono fino a diventare gusci pietrificati, ma i loro spiriti rimasero. Una foglia di uno di loro, Vartrus, fin\xec nel tesoro del Signore del Fuoco nel Nucleo Ardente.","Nel gioco originale, il cacciatore che riportava la foglia a Vartrus veniva mandato a cacciare da solo quattro agenti della Legione, senza neppure un famiglio. In cambio, gli Antichi creavano Rhok'delar, un arco lungo che fiorisce da s\xe9, e il suo compagno Lok'delar, un bastone che risplende del potere della natura."]},"item:taelans-hammer":{title:"Il Martello di Taelan",summary:"Il martello giocattolo di un bambino, che aiut\xf2 Tirion Fordring a raggiungere il figlio che la Crociata Scarlatta gli aveva portato via.",body:["Per il suo settimo compleanno, il piccolo Taelan ricevette dal padre, Tirion Fordring, un martello da guerra in miniatura, copia di quello di Tirion. Dopo che Tirion fu esiliato per aver difeso l\u2019orco Eitrigg, la madre di Taelan disse al bambino che suo padre era morto e lo port\xf2 davanti a una falsa tomba nell\u2019Undercroft, nelle Terre Infette Orientali, dove lui seppell\xec il martello e, con esso, il ricordo.","Anni dopo Taelan divenne Alto Signore della Crociata Scarlatta a Hearthglen. Nel gioco originale, gli avventurieri recuperavano il martello per l\u2019ormai anziano Tirion e aiutavano Taelan a vedere che cosa fosse diventata la Crociata. Mentre fuggiva da Hearthglen, il Grande Inquisitore Isillien lo abbatt\xe9 sotto gli occhi del padre; Tirion uccise Isillien e giur\xf2 di riforgiare la Mano d\u2019Argento."]},"item:heart-of-hakkar":{title:"Cuore di Hakkar",summary:"Il cuore ancora ardente del Dio del Sangue, portato agli Zandalari dopo che Hakkar fu ucciso a Zul'Gurub.",body:["Circa quindici secoli prima del Portale Oscuro, gli affamati troll Gurubashi si rivolsero a Hakkar the Soulflayer, un loa del sangue. Lui diede loro potere e un impero, poi pretese sempre pi\xf9 vite, finch\xe9 le trib\xf9 non si ribellarono contro di lui ed esiliarono i suoi sacerdoti Atal'ai. Quando i sacerdoti innalzarono un tempio per riportarlo indietro, Ysera lo distrusse e lo sprofond\xf2 sotto gli acquitrini della Palude del Dolore.","Nel gioco originale, i sacerdoti Hakkari riuscirono infine ad attirare il Soulflayer a Zul'Gurub. Gli eroi radunati dalla trib\xf9 Zandalar lo uccisero l\xec e portarono il suo cuore ancora luminoso a Molthor, sull\u2019Isola di Yojamba, il cui rito benediceva con lo Spirito di Zandalar tutti quelli che si trovavano sull\u2019isola e alla Baia del Bottino."]},"item:phylactery-of-kelthuzad":{title:"Il Filatterio di Kel'Thuzad",summary:"Il ricettacolo che custodisce l\u2019anima dell\u2019arcilich, sottratto a Naxxramas dopo la sua sconfitta.",body:["Kel'Thuzad, un tempo arcimago del Kirin Tor, fond\xf2 il Culto dei Dannati e diffuse la piaga per il Re dei Lich. Ucciso da Arthas e in seguito portato al Pozzo Solare per rinascere come lich, fin\xec per governare il Flagello in Lordaeron dalla necropoli fluttuante di Naxxramas.","Un lich sopravvive finch\xe9 resiste il ricettacolo che ne custodisce l\u2019anima. Nel gioco originale, le incursioni che sconfiggevano Kel'Thuzad recuperavano il suo filatterio e lo affidavano all\u2019Alba d\u2019Argento perch\xe9 lo custodisse. Storie successive rivelarono che uno dei suoi sacerdoti, padre Inigo Montoy, trad\xec quella fiducia e lo port\xf2 in Nordania, dando all\u2019arcilich il tempo di tornare."]}}},1778,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"terms",{enumerable:!0,get:function(){return o}});const o={"term:argent-dawn":{title:"Alba d\u2019Argento",summary:"Un ordine che ha giurato di difendere Azeroth dal Flagello senza l\u2019odio cieco della Crociata Scarlatta.",body:["Quando i superstiti della Mano d\u2019Argento a Lordaeron si irrigidirono fino a diventare la fanatica Crociata Scarlatta, alcuni si rifiutarono di seguirli. Guidati da figure come Lord Maxwell Tyrosus, fondarono l\u2019Alba d\u2019Argento, che accoglie chiunque sia disposto a combattere i non-morti. Dalla Light's Hope Chapel, nelle Terre Infette Orientali, l\u2019ordine sorveglia il Flagello e ricompensa chi aiuta a tenere la linea."]},"term:burning-legion":{title:"Legione Infuocata",summary:"L\u2019esercito infinito di demoni del titano caduto Sargeras, che ha giurato di bruciare l\u2019intera creazione.",body:["Un tempo campione del Pantheon dei Titani, Sargeras scopr\xec che le potenze del Vuoto volevano corrompere le anime-mondo e, nella disperazione, decise di bruciare la creazione piuttosto che lasciarla a loro. Liber\xf2 i demoni che aveva imprigionato e convinse i signori eredar Kil'jaeden e Archimonde a comandarli. La Legione invase Azeroth nella Guerra degli Antichi e di nuovo nella Terza Guerra, e i suoi agenti si annidano ancora in luoghi come il Vilbosco e le Terre Devastate."]},"term:cenarion-circle":{title:"Circolo Cenariano",summary:"L\u2019ordine druidico di Elfi della Notte e tauren che veglia sull\u2019equilibrio della natura dalla Radura Lunare.",body:["Chiamato cos\xec in onore del semidio Cenarius, che istru\xec i primi druidi, il Circolo unisce druidi Elfi della Notte e tauren in un unico ordine. Il suo cuore \xe8 il villaggio di Nighthaven, nella Radura Lunare, un santuario dove combattere \xe8 proibito, e i suoi membri sorvegliano anche i pericoli di Silithus dal Presidio Cenariano."]},"term:cult-of-the-damned":{title:"Culto dei Dannati",summary:"Il culto del Re dei Lich fondato da Kel'Thuzad, che prometteva la vita eterna e port\xf2 la piaga.",body:["L\u2019arcimago Kel'Thuzad volt\xf2 le spalle al Kirin Tor per studiare la negromanzia e radun\xf2 i poveri e i disperati di Lordaeron con la promessa di una vita migliore, senza morte. Il culto nascose la piaga del Re dei Lich in carichi di grano, trasformando interi villaggi in Flagello. I suoi negromanti insegnano ancora nella Scholomance, a Caer Darrow, l\u2019antica fortezza della famiglia Barov."]},"term:dark-portal":{title:"Portale Oscuro",summary:"Il varco tra Draenor e Azeroth attraverso cui l\u2019Orda degli orchi invase il mondo.",body:["Lo stregone orco Gul'dan e il Guardiano posseduto Medivh aprirono il Portale Oscuro, collegando Draenor alla Palude Nera di Azeroth. La sua apertura diede inizio alla Prima Guerra, e gli anni della storia di Warcraft si contano ancora da quel momento. L\u2019Alleanza lo distrusse dopo la Seconda Guerra, Ner'zhul lo riapr\xec con la forza e Khadgar lo fece crollare dal lato di Draenor. La sua struttura inattiva torreggia ancora sulle Terre Devastate."]},"term:defias-brotherhood":{title:"Confraternita Defias",summary:"Scalpellini di Roccavento mai pagati, diventati banditi sotto la guida di Edwin VanCleef.",body:["La Gilda degli Scalpellini ricostru\xec Roccavento dopo la Seconda Guerra, ma i nobili si rifiutarono di pagarla. Il suo capo, Edwin VanCleef, guid\xf2 gli scalpellini infuriati nelle Marche Occidentali e ne fece la Confraternita Defias, una banda di ladri e sabotatori nascosta nelle Miniere della Morte. In Forever i suoi membri compaiono anche dentro Alcaz Prison, impegnati in una lotta con i naga."]},"term:dragon-aspects":{title:"Aspetti dei Draghi",summary:"Cinque grandi draghi a cui i Titani diedero il potere di custodire Azeroth, ognuno a capo di uno stormo.",body:["I Titani scelsero cinque draghi e diedero a ciascuno una parte del loro potere: Alexstrasza la Custode della Vita, dello stormo rosso; Ysera la Sognatrice, del verde; Nozdormu il Senza Tempo, del bronzeo; Malygos il Tessitore di Incantesimi, del blu; e Neltharion il Custode della Terra, del nero. Il tradimento di Neltharion lo trasform\xf2 in Alamorte, e i suoi figli Onyxia e Nefarian tramano ancora su Azeroth."]},"term:elemental-lords":{title:"Signori degli Elementi",summary:"I quattro sovrani di fuoco, terra, aria e acqua, un tempo servitori degli Dei Antichi.",body:["Ragnaros del fuoco, Therazane della terra, Al'Akir dell\u2019aria e Neptulon dell\u2019acqua guidarono gli elementali nella guerra degli Dei Antichi contro i servitori dei Titani. Quando l\u2019Impero Nero cadde, i custodi li imprigionarono nel Piano Elementale. Gli sciamani cercano di mantenere gli elementi in equilibrio, mentre l\u2019errore dello stregone Ferroscuro Thaurissan ha riportato Ragnaros nel mondo, sotto il Massiccio Roccianera."]},"term:elune":{title:"Elune",summary:"La dea della luna degli Elfi della Notte, le cui sacerdotesse guidano il loro popolo.",body:["Gli Elfi della Notte venerano Elune fin dagli albori della loro civilt\xe0 e trovano una guida nella luce della luna. La Sorellanza di Elune, guidata dall\u2019alta sacerdotessa Tyrande Soffiabrezza, fa al tempo stesso da clero e da governo a Darnassus, e i sacerdoti Elfi della Notte traggono dalla dea il loro potere di guarigione."]},"term:emerald-dream":{title:"Sogno di Smeraldo",summary:"Un riflesso onirico delle terre selvagge e incontaminate di Azeroth, custodito da Ysera e percorso dai druidi.",body:["Il Sogno di Smeraldo riflette il mondo come sarebbe potuto essere senza mani mortali. Ysera e il suo stormo verde lo custodiscono, e i druidi vi entrano in spirito, a volte dormendo per secoli. Nel presente di Azeroth qualcosa sta guastando il Sogno: un incubo strisciante distorce i sogni di Naralex nelle Caverne dei Lamenti e ha fatto impazzire i draghi verdi del Tempio Sommerso."]},"term:explorers-league":{title:"Lega degli Esploratori",summary:"La societ\xe0 di archeologi nanici di Forgiardente, che scava alla ricerca dei segreti dei Titani.",body:["Dalla Sala degli Esploratori di Forgiardente, la Lega manda nani in tutto il mondo alla ricerca di reliquie che possano spiegare da dove venga il loro popolo. Il suo membro pi\xf9 famoso \xe8 Brann Barbabronzea, l\u2019irrequieto fratello del re. Gli scavatori della Lega hanno riportato alla luce le camere dei Titani di Uldaman, e in Forever le strane rovine congelate nel tempo oltre il Whelgar's Excavation Site, nelle Wetlands, sono proprio il genere di mistero a cui la Lega d\xe0 la caccia."]},"term:fel":{title:"Magia vile",summary:"La magia ardente e corruttrice della Legione Infuocata.",body:["La magia vile \xe8 la magia dei demoni: potente, assuefacente e rovinosa per tutto ci\xf2 che tocca. Gli stregoni di Gul'dan la usarono per prosciugare la vita di Draenor e legare gli orchi alla Legione, e la sua contaminazione ne rese verde la pelle. Gli stregoni la usano ancora oggi, e le sue cicatrici segnano il Vilbosco, dove la corruzione demoniaca ha avvelenato un\u2019antica foresta."]},"term:guardian-of-tirisfal":{title:"Guardiano di Tirisfal",summary:"Un mago che riceve il potere unito di un consiglio segreto per combattere da solo la Legione Infuocata.",body:["Maghi Elfi Alti e umani fondarono il segreto Consiglio di Tirisfal per impedire che i demoni si infiltrassero nel mondo attraverso una magia sconsiderata. In ogni epoca il consiglio riversava il proprio potere in un unico campione, il Guardiano. Aegwynn ricopr\xec quel ruolo per secoli; suo figlio Medivh, l\u2019ultimo Guardiano, era segretamente posseduto da Sargeras e apr\xec la strada agli orchi."]},"term:highborne":{title:"Highborne",summary:"L\u2019aristocrazia arcana dell\u2019antico impero degli Elfi della Notte, la cui sete di magia attir\xf2 la Legione.",body:["Gli Highborne servivano la regina Azshara come sua corte e suoi stregoni, attingendo sempre pi\xf9 a fondo al Pozzo dell\u2019Eternit\xe0 finch\xe9 i loro incantesimi non attirarono l\u2019attenzione di Sargeras. Dopo la Grande Frattura, la maggior parte dei superstiti fu esiliata e fond\xf2 Quel'Thalas come Elfi Alti. Altri, gli Shen'dralar, rimasero nascosti a Eldre'Thalas, la citt\xe0 oggi chiamata Maglio Infausto."]},"term:holy-light":{title:"La Luce Sacra",summary:"Il potere della speranza e della virt\xf9 incanalato da paladini e sacerdoti.",body:["Gli umani venerano la Luce attraverso la Chiesa della Luce Sacra, i cui chierici guariscono i feriti e le cui cattedrali si innalzano a Roccavento e un tempo si innalzavano a Lordaeron. Anche i nani la abbracciarono. Durante la Seconda Guerra l\u2019arcivescovo Alonsus Faol un\xec fede e acciaio fondando i paladini della Mano d\u2019Argento, e la Luce rimane la rovina dei non-morti."]},"term:kaldorei":{title:"Kaldorei",summary:"Gli Elfi della Notte, i \xabfigli delle stelle\xbb, una delle civilt\xe0 pi\xf9 antiche di Kalimdor.",body:["Discendenti da troll trasformati dal Pozzo dell\u2019Eternit\xe0, gli Elfi della Notte costruirono sotto la regina Azshara un impero abbagliante prima che sprofondasse nella Grande Frattura. Per diecimila anni vissero come druidi e Sentinelle, senza invecchiare grazie a Nordrassil, finch\xe9 la Terza Guerra non cost\xf2 loro l\u2019immortalit\xe0. Oggi governano da Darnassus, in cima a Teldrassil, e stanno al fianco dell\u2019Alleanza."]},"term:kirin-tor":{title:"Kirin Tor",summary:"Il consiglio di maghi che governa Dalaran e custodisce la magia pericolosa.",body:["Fondato nella citt\xe0 dei maghi, Dalaran, il Kirin Tor sovrintende allo studio della magia arcana e rinchiude gli artefatti troppo pericolosi per il mondo. Archimonde lasci\xf2 Dalaran in rovina durante la Terza Guerra, e nel gioco originale la citt\xe0 restava nascosta sotto una cupola viola. In Forever quella barriera \xe8 caduta e rivela un restauro travolto da un caos arcano impazzito."]},"term:ley-lines":{title:"Linee Ley",summary:"Correnti di energia arcana che attraversano Azeroth come vene.",body:["Le linee ley trasportano potere arcano grezzo per il mondo, e dove si incrociano la magia si fa pi\xf9 forte. Gli Elfi Alti innalzarono il Pozzo Solare in uno di questi nodi, e i maghi cercano da tempo queste correnti. In Forever gli Skyborne dell\u2019High Order possono attingervi con la loro abilit\xe0 razziale Read Ley Line, che dura molto pi\xf9 a lungo se usata vicino a una di esse."]},"term:lich-king":{title:"Re dei Lich",summary:"Il signore immortale del Flagello, in trono tra i ghiacci di Nordania.",body:["Kil'jaeden strapp\xf2 lo spirito dello sciamano orco Ner'zhul dal suo corpo e lo sigill\xf2 in un blocco di ghiaccio in cima a Corona di Ghiaccio, il Trono di Ghiaccio, per preparare Azeroth all\u2019arrivo della Legione. Da l\xec il Re dei Lich sollev\xf2 il Flagello e diffuse la piaga. Dopo la Terza Guerra il principe Arthas sal\xec sul trono e si fuse con lui, e il Re dei Lich cos\xec unito attende ora a Nordania."]},"term:loa":{title:"Loa",summary:"I potenti spiriti animali e dei venerati dai troll.",body:["Ogni trib\xf9 troll onora i loa, spiriti antichi che spesso assumono la forma di grandi bestie, e contratta con loro per ottenere forza. Alcuni sono volubili ma giusti, altri crudeli. Hakkar the Soulflayer, il loa del sangue, per poco non divor\xf2 l\u2019Impero Gurubashi, e i suoi seguaci si agitano ancora a Rovotorto e nella Palude del Dolore."]},"term:nathrezim":{title:"Nathrezim",summary:"I Signori del Terrore: demoni astuti e vampireschi che servono la Legione con l\u2019inganno.",body:["I nathrezim preferiscono i sussurri alla guerra aperta. La Legione incaric\xf2 Signori del Terrore come Mal'Ganis, Tichondrius e Balnazzar di sorvegliare il Re dei Lich e di guidare la conquista di Lordaeron da parte del Flagello. Quando il Re dei Lich si liber\xf2 di loro si dispersero, ma alcuni si nascondono ancora sotto gli occhi di tutti: Balnazzar porta il volto del Gran Crociato della Crociata Scarlatta."]},"term:nordrassil":{title:"Nordrassil",summary:"L\u2019Albero del Mondo del Monte Hyjal, piantato dagli Aspetti per sigillare il secondo Pozzo dell\u2019Eternit\xe0.",body:["Dopo la Grande Frattura, Illidan vers\xf2 in segreto l\u2019acqua rubata dal Pozzo dell\u2019Eternit\xe0 in un lago del Monte Hyjal. Per sigillare questo nuovo pozzo, gli Aspetti dei Draghi piantarono un seme incantato che crebbe fino a diventare Nordrassil, e la sua benedizione rese gli Elfi della Notte immuni all\u2019invecchiamento. La caduta di Archimonde ai suoi piedi fer\xec l\u2019albero, e l\u2019incursione Hyjal Summit di Forever sale fino alla vetta accanto a esso."]},"term:old-gods":{title:"Dei Antichi",summary:"Antichi esseri del Vuoto che si seppellirono in Azeroth per corromperne l\u2019anima-mondo.",body:["Molto prima che i mortali camminassero sul mondo, gli Dei Antichi, tra cui C'Thun, Yogg-Saron, N'Zoth e Y'Shaarj, si schiantarono su Azeroth e innalzarono un Impero Nero. Strappare via Y'Shaarj fer\xec il mondo stesso, perci\xf2 i Titani scelsero di imprigionare gli altri sottoterra. I loro sussurri spingono ancora culti come il Martello del Crepuscolo, e C'Thun si agita sotto Ahn'Qiraj, a Silithus."]},"term:silver-hand":{title:"Ordine della Mano d\u2019Argento",summary:"Il primo ordine di paladini, fondato a Lordaeron durante la Seconda Guerra.",body:["L\u2019arcivescovo Alonsus Faol cap\xec che i soli chierici non sarebbero sopravvissuti all\u2019Orda, cos\xec addestr\xf2 dei guerrieri nelle vie della Luce. Uther il Portatore di Luce divenne il primo dei Cavalieri della Mano d\u2019Argento. L\u2019ordine combatt\xe9 per tutta la Seconda Guerra, ma la caduta di Arthas lo spezz\xf2: Uther mor\xec per mano del suo ex allievo, e molti superstiti finirono nella Crociata Scarlatta."]},"term:queldorei":{title:"Quel'dorei",summary:"Gli Elfi Alti di Quel'Thalas, eredi degli Highborne esiliati.",body:["Quasi settemila anni prima del Portale Oscuro, alcuni Highborne esiliati attraversarono il mare, fondarono Quel'Thalas e accesero il Pozzo Solare. Si allearono con gli umani di Arathor nelle Guerre dei Troll e insegnarono loro la magia. Quando il Flagello di Arthas devast\xf2 il loro regno e profan\xf2 il Pozzo Solare, la maggior parte dei superstiti prese un nuovo nome in memoria dei propri morti: i sin'dorei, o Elfi del Sangue."]},"term:scarlet-crusade":{title:"Crociata Scarlatta",summary:"Fanatici che danno la caccia ai non-morti e a chiunque sospettino di portare la piaga, guidati in segreto da un Signore del Terrore.",body:["Nata dai paladini e dai soldati superstiti di Lordaeron, la Crociata giur\xf2 di purgare il Flagello, ma divenne cos\xec fanatica da attaccare tanto i Reietti quanto i viaggiatori vivi. Il suo Gran Crociato \xe8 in segreto il Signore del Terrore Balnazzar. Tra le sue roccaforti ci sono il Monastero Scarlatto nelle Radure di Tirisfal, Hearthglen e la Mano di Tyr."]},"term:scourge":{title:"Flagello",summary:"L\u2019esercito di non-morti del Re dei Lich, diffuso dalla piaga e dalla negromanzia.",body:["Il Flagello \xe8 legato alla volont\xe0 del Re dei Lich: ghoul, abomini, lich e cavalieri della morte risorti dai caduti. La piaga che lo ha creato travolse Lordaeron nella Terza Guerra e si lasci\xf2 dietro le Terre Infette. Sotto Kel'Thuzad il Flagello tiene ancora Stratholme e la Scholomance, e la sua portata arriva fino a Razorfen Downs, nelle Savane."]},"term:skywall":{title:"Skywall",summary:"Il Piano Elementale dell\u2019aria, regno di Al'Akir, il Signore del Vento.",body:["Quando i servitori dei Titani imprigionarono gli elementali, i signori dell\u2019aria furono confinati a Skywall, un regno di cielo infinito governato da Al'Akir. In Forever Skywall ospita anche Zephras Isle, la zona iniziale fluttuante degli Skyborne. Gli elementali dell\u2019aria dell\u2019isola sono scomparsi secoli fa, e la magia che la tiene sospesa si sta lentamente esaurendo."]},"term:sunwell":{title:"Pozzo Solare",summary:"La fonte di potere arcano nel cuore di Quel'Thalas.",body:["Dath'Remar Solealto vers\xf2 una fiala rubata dal Pozzo dell\u2019Eternit\xe0 in un lago in cui si incontrano diverse linee ley, e il Pozzo Solare prese vita in un bagliore. Per millenni aliment\xf2 la magia e la cultura degli Elfi Alti. Durante la Terza Guerra Arthas ne us\xf2 le acque per far risorgere Kel'Thuzad come lich e profan\xf2 la fonte; la sua perdita lasci\xf2 ai superstiti una fame di magia che non li ha pi\xf9 abbandonati."]},"term:titan-forged":{title:"Forgiati dai Titani",summary:"I custodi e gli altri servitori che i Titani crearono per portare ordine su Azeroth.",body:["I Titani plasmarono servitori che completassero la loro opera: custodi imponenti e razze di pietra e metallo come i terrigeni e i meccagnomi. Nel corso delle ere, la Maledizione della Carne degli Dei Antichi rese mortali molti di loro, e da essi discendono i nani e gli gnomi. Guardiani forgiati dai Titani custodiscono ancora camere come Uldaman, e Forever aggiunge altri siti dei Titani, dallo scavo nelle Wetlands fino a Shaper's Terrace, nel Cratere di Un'Goro."]},"term:titans":{title:"Titani",summary:"Colossali anime-mondo che cercarono di portare ordine nel cosmo e plasmarono Azeroth.",body:["I Titani sono anime-mondo risvegliate in esseri divini. Il loro Pantheon, guidato da Aman'Thul, percorse il cosmo in cerca di anime-mondo addormentate e ne trov\xf2 una molto promettente dentro Azeroth. Strapparono dal mondo il Dio Antico Y'Shaarj, imprigionarono gli altri e lasciarono ai loro servitori il compito di plasmare la terra. Il loro campione pi\xf9 potente, Sargeras, cadde in seguito e fond\xf2 la Legione Infuocata."]},"term:twilights-hammer":{title:"Martello del Crepuscolo",summary:"Un tempo un clan di orchi, oggi un culto apocalittico al servizio degli Dei Antichi.",body:["Guidato dal mago ogre a due teste Cho'gall, il Martello del Crepuscolo combatt\xe9 nella Seconda Guerra come clan di orchi prima di trasformarsi in un culto che anela alla fine del mondo. I suoi membri, provenienti da ogni razza, si radunano in luoghi come gli Abissi Neri e Silithus. In Forever il culto occupa anche le rovine di Sunnyglade, nelle Riverglades."]},"term:well-of-eternity":{title:"Pozzo dell\u2019Eternit\xe0",summary:"Il lago di potere arcano grezzo nel cuore dell\u2019antica Kalimdor, la cui implosione spacc\xf2 il mondo.",body:["Il Pozzo si form\xf2 dove i Titani strapparono Y'Shaarj dal mondo, e i custodi placarono la ferita sanguinante trasformandola in un lago di puro potere. Gli Elfi della Notte costruirono il loro impero sulle sue rive, e gli incantesimi sconsiderati degli Highborne vi attirarono la Legione. Il suo crollo nella Guerra degli Antichi provoc\xf2 la Grande Frattura, e il Maelstrom vortica l\xe0 dove un tempo si trovava."]}}},1779,[]);